BEGIN;
SET search_path TO public;

-- Preguntas 1801 a 1900
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (1801, 'SUB-1801', 'SBM4', 'DURANTE LAS AUDIENCIAS, CONTRA TODO TIPO DE RESOLUCIÓN, QUE RECURSO SERÁ ADMISIBLE:', 'RECURSO DE REPOSICIÓN', 'ART. 415', '184637'),
    (1802, 'SUB-1802', 'SBM4', 'POR LA COMPETENCIA SE PRECISA E IDENTIFICA A LOS ÓRGANOS JURISDICCIONALES QUE DEBEN CONOCER:', 'UN PROCESO', 'ART. 19', '184638'),
    (1803, 'SUB-1803', 'SBM4', 'ADMITIDO EL RECURSO DE REPOSICIÓN CONTRA TODO TIPO DE RESOLUCIÓN, EL JUEZ EN QUE PLAZO RESOLVERÁ EL RECURSO:', 'EN ESE MISMO ACTO SIN SUSPENDER LA AUDIENCIA', 'ART. 415', '184639'),
    (1804, 'SUB-1804', 'SBM4', 'EL AUTO QUE RESUELVE LA REPOSICIÓN ES:', 'INIMPUGNABLE', 'ART. 415', '184640'),
    (1805, 'SUB-1805', 'SBM4', 'LAS CUESTIONES DE COMPETENCIA NO SUSPENDERÁN EL PROCEDIMIENTO. NO OBSTANTE, SI SE PRODUCEN ANTES DE DICTARSE EL AUTO DE CITACIÓN DE JUICIO, SE:', 'SUSPENDERÁ LA AUDIENCIA HASTA LA DECISIÓN DEL CONFLICTO', 'ART. 20', '184641'),
    (1806, 'SUB-1806', 'SBM4', 'LA COMPETENCIA POR RAZÓN DEL TERRITORIO SE ESTABLECE EN EL SIGUIENTE ORDEN:', 'POR EL LUGAR DONDE SE COMETIÓ EL HECHO DELICTUOSO O SE REALIZÓ EL ÚLTIMO ACTO', 'ART. 21', '184642'),
    (1807, 'SUB-1807', 'SBM4', '¿EN QUÉ CASO PROCEDERÁ EL RECURSO DE APELACIÓN?', 'CONTRA LOS AUTOS DE SOBRESEIMIENTO QUE RESUELVAN CUESTIONES PREVIAS', 'ART. 416', '184643'),
    (1808, 'SUB-1808', 'SBM4', 'LA ACTUACIÓN PROCESAL, FISCAL O JUDICIAL, SE DOCUMENTA:.', 'POR MEDIO DE ACTA.', 'ART. 120. Num. 1', '184644'),
    (1809, 'SUB-1809', 'SBM4', '¿EN QUÉ CASO PROCEDERÁ EL RECURSO DE APELACIÓN?', 'CONTRA LOS AUTOS QUE RESUELVAN CUESTIONES PREJUDICIALES Y EXCEPCIONES', 'ART. 416', '184645'),
    (1810, 'SUB-1810', 'SBM4', 'LA COMPETENCIA POR RAZÓN DEL TERRITORIO SE ESTABLECE EN EL SIGUIENTE ORDEN:', 'POR EL LUGAR DONDE SE PRODUJERON LOS EFECTOS DEL DELITO', 'ART. 21', '184646'),
    (1811, 'SUB-1811', 'SBM4', 'EN QUE CASO PROCEDERÁ EL RECURSO DE APELACIÓN.', 'CONTRA LOS AUTOS QUE REVOQUEN LA CONDENA CONDICIONAL', 'ART. 416', '184647'),
    (1812, 'SUB-1812', 'SBM4', 'EL ACTA DEBE SER FECHADA CON INDICACIÓN DEL:.', 'LUGAR, AÑO, MES, DÍA Y HORA EN QUE HAYA SIDO REDACTADA.', 'ART. 120. Num. 2', '184648'),
    (1813, 'SUB-1813', 'SBM4', 'LA COMPETENCIA POR RAZÓN DEL TERRITORIO SE ESTABLECE EN EL SIGUIENTE ORDEN:', 'POR EL LUGAR DONDE SE DESCUBRIERON LAS PRUEBAS MATERIALES DEL DELITO', 'ART. 21', '184649'),
    (1814, 'SUB-1814', 'SBM4', '¿EN QUÉ CASO PROCEDERÁ EL RECURSO DE APELACIÓN?', 'CONTRA LOS AUTOS QUE REVOQUEN LA RESERVA DEL FALLO CONDENATORIO', 'ART. 416', '184650'),
    (1815, 'SUB-1815', 'SBM4', '¿EN QUÉ CASO PROCEDERÁ EL RECURSO DE APELACIÓN?', 'CONTRA LOS AUTOS QUE REVOQUEN LA CONVERSIÓN DE LA PENA', 'ART. 416', '184651'),
    (1816, 'SUB-1816', 'SBM4', 'SE DEBE HACER CONSTAR EN EL ACTA EL CUMPLIMIENTO DE:.', 'LAS DISPOSICIONES ESPECIALES PREVISTAS PARA LAS ACTUACIONES QUE ASÍ LO REQUIERAN', 'ART. 120. Num. 2', '184652'),
    (1817, 'SUB-1817', 'SBM4', 'LA COMPETENCIA POR RAZÓN DEL TERRITORIO SE ESTABLECE EN EL SIGUIENTE ORDEN:', 'POR EL LUGAR DONDE FUE DETENIDO EL IMPUTADO', 'ART. 21', '184653'),
    (1818, 'SUB-1818', 'SBM4', '¿EN QUÉ CASO PROCEDERÁ EL RECURSO DE APELACIÓN?', 'CONTRA LOS AUTOS QUE SE PRONUNCIEN SOBRE LA CONSTITUCIÓN DE LAS PARTES', 'ART. 416', '184654'),
    (1819, 'SUB-1819', 'SBM4', 'CUANDO LA SALA PENAL SUPERIOR TENGA SU SEDE EN UN LUGAR DISTINTO DEL JUZGADO, EL RECURRENTE EN QUE PLAZO DEBERÁ FIJAR DOMICILIO PROCESAL EN LA SEDE DE CORTE ...', 'DENTRO DEL QUINTO DÍA DE NOTIFICADO EL CONCESORIO', 'ART. 416', '184655'),
    (1820, 'SUB-1820', 'SBM4', 'LA COMPETENCIA POR RAZÓN DEL TERRITORIO SE ESTABLECE EN EL SIGUIENTE ORDEN:', 'POR EL LUGAR DONDE DOMICILIA EL IMPUTADO', 'ART. 21', '184656'),
    (1821, 'SUB-1821', 'SBM4', 'SERÁ POSIBLE LA REPRODUCCIÓN AUDIOVISUAL DE LA ACTUACIÓN PROCESAL, SIN PERJUICIO DE:.', 'EFECTUARSE LA TRANSCRIPCIÓN RESPECTIVA EN EL ACTA.', 'ART. 120. Num. 3', '184657'),
    (1822, 'SUB-1822', 'SBM4', 'CONTRA LAS DECISIONES EMITIDAS POR EL JUEZ DE LA INVESTIGACIÓN PREPARATORIA, ¿QUÉ AUTORIDAD CONOCE EL RECURSO?', 'LA SALA PENAL SUPERIOR', 'ART. 417', '184658'),
    (1823, 'SUB-1823', 'SBM4', 'SI EL DELITO ES COMETIDO EN UN MEDIO DE TRANSPORTE SIN QUE SEA POSIBLE DETERMINAR CON PRECISIÓN LA COMPETENCIA TERRITORIAL, CORRESPONDE CONOCER AL:', 'JUEZ DEL LUGAR DE LLEGADA MÁS PRÓXIMO', 'ART. 22', '184659'),
    (1824, 'SUB-1824', 'SBM4', 'CONTRA LAS DECISIONES EMITIDAS POR EL JUZGADO PENAL, UNIPERSONAL O COLEGIADO, QUE AUTORIDAD CONOCE EL RECURSO', 'SALA PENAL SUPERIOR', 'ART. 417', '184660'),
    (1825, 'SUB-1825', 'SBM4', 'LA AUTORIDAD POLICIAL INFORMARÁ DE INMEDIATO AL FISCAL PROVINCIAL PARA QUE PROCEDA CON:', 'ARREGLO A SUS ATRIBUCIONES', 'ART. 22', '184661'),
    (1826, 'SUB-1826', 'SBM4', 'CONTRA LAS SENTENCIAS EMITIDAS POR EL JUZGADO DE PAZ LETRADO, ¿QUÉ AUTORIDAD CONOCE DEL RECURSO?', 'EL JUZGADO PENAL UNIPERSONAL', 'ART. 417', '184662'),
    (1827, 'SUB-1827', 'SBM4', 'LA FISCALÍA DE LA NACIÓN Y EL CONSEJO EJECUTIVO DEL PODER JUDICIAL, DICTARÁN DISPOSICIONES QUE PERMITAN SU UTILIZACIÓN.', 'CADA UNO EN SU ÁMBITO, EN FUNCIÓN A LAS POSIBILIDADES DE LA INSTITUCIÓN.', 'ART. 120. Num. 3', '184663'),
    (1828, 'SUB-1828', 'SBM4', 'SI EL DELITO ES COMETIDO FUERA DEL TERRITORIO NACIONAL Y DEBE SER JUZGADO EN EL PERÚ CONFORME AL CÓDIGO PENAL, LA COMPETENCIA DEL JUEZ SE ESTABLECE EN EL SIGUIENTE ORDEN:', 'POR EL LUGAR DONDE EL IMPUTADO TUVO SU ÚLTIMO DOMICILIO EN EL PAÍS', 'ART. 23', '184664'),
    (1829, 'SUB-1829', 'SBM4', 'SI EL DELITO ES COMETIDO FUERA DEL TERRITORIO NACIONAL Y DEBE SER JUZGADO EN EL PERÚ CONFORME AL CÓDIGO PENAL, LA COMPETENCIA DEL JUEZ SE ESTABLECE EN EL SIGUIENTE ORDEN:', 'POR EL LUGAR DE LLEGADA DEL EXTRANJERO', 'ART. 23', '184665'),
    (1830, 'SUB-1830', 'SBM4', 'EL EXAMEN DE LA SALA PENAL SUPERIOR TIENE COMO PROPÓSITO QUE LA RESOLUCIÓN IMPUGNADA SEA:', 'ANULADA O REVOCADA, TOTAL O PARCIALMENTE', 'ART. 419', '184666'),
    (1831, 'SUB-1831', 'SBM4', 'EL ACTA SERÁ SUSCRITA POR EL FUNCIONARIO O AUTORIDAD QUE:.', 'DIRIGE Y POR LOS DEMÁS INTERVINIENTES, PREVIA LECTURA.', 'ART. 120. Num. 4', '184667'),
    (1832, 'SUB-1832', 'SBM4', 'SI EL DELITO ES COMETIDO FUERA DEL TERRITORIO NACIONAL Y DEBE SER JUZGADO EN EL PERÚ CONFORME AL CÓDIGO PENAL, LA COMPETENCIA DEL JUEZ SE ESTABLECE EN EL SIGUIENTE ORDEN:', 'POR EL LUGAR DONDE SE ENCUENTRE EL IMPUTADO AL MOMENTO DE PROMOVERSE LA ACCIÓN PENAL', 'ART. 23', '184668'),
    (1833, 'SUB-1833', 'SBM4', 'EL AUTO EN EL QUE LA SALA DECLARA INADMISIBLE EL RECURSO PODRÁ SER OBJETO DE RECURSO DE:', 'REPOSICIÓN', 'ART. 420', '184669'),
    (1834, 'SUB-1834', 'SBM4', '¿CUÁL DE LOS SIGUIENTES PRESUPUESTOS MATERIALES ES INDISPENSABLE PARA QUE EL JUEZ DICTE MANDATO DE PRISIÓN PREVENTIVA, SEGÚN EL ARTÍCULO 268 DEL CÓDIGO PROCESAL PENAL?', 'QUE EXISTAN FUNDADOS Y GRAVES ELEMENTOS DE CONVICCIÓN QUE VINCULEN AL IMPUTADO COMO AUTOR O PARTÍCIPE DEL DELITO', 'ART. 268', '184673'),
    (1835, 'SUB-1835', 'SBM4', 'SEGÚN EL ARTÍCULO 268 DEL CÓDIGO PROCESAL PENAL, ¿EN QUÉ SUPUESTOS PUEDE EL JUEZ COLEGIR RAZONABLEMENTE EL PELIGRO DE FUGA U OBSTACULIZACIÓN?', 'EN RAZÓN A LOS ANTECEDENTES Y OTRAS CIRCUNSTANCIAS DEL CASO PARTICULAR DEL IMPUTADO', 'ART. 268', '184674'),
    (1836, 'SUB-1836', 'SBM4', '¿EN QUÉ CASOS NO PROCEDE LA PRISIÓN PREVENTIVA SEGÚN LO ESTABLECIDO EN EL ARTÍCULO 268, SALVO CIRCUNSTANCIAS EXCEPCIONALES?', 'EN LOS CASOS DE INMINENTE APLICACIÓN DE LEGÍTIMA DEFENSA PROPIA O DE TERCERO CONFORME A LEY', 'ART. 268', '184675'),
    (1837, 'SUB-1837', 'SBM4', 'ARTÍCULO N° 268.- PRESUPUESTOS MATERIALES. EL JUEZ, A SOLICITUD DEL MINISTERIO PÚBLICO, PODRÁ DICTAR MANDATO DE PRISIÓN PREVENTIVA, SI ATENDIENDO A LOS PRIMEROS RECAUDOS SEA POSIBLE DETERMINAR LA CONCURRENCIA DE LOS SIGUIENTES PRESUPUESTOS: QUE LA SANCIÓN A IMPONERSE SEA SUPERIOR A:', 'CINCO AÑOS', 'ART. 268', '184676'),
    (1838, 'SUB-1838', 'SBM4', 'DE ACUERDO CON EL ARTÍCULO 138, ¿EN QUÉ SITUACIONES PUEDE EL MINISTERIO PÚBLICO SOLICITAR COPIAS DE ACTUACIONES DE OTROS PROCESOS?', 'CUANDO SEA NECESARIO PARA EL CUMPLIMIENTO DE LA INVESTIGACIÓN PREPARATORIA, DE OTRO FISCAL O DEL JUEZ', 'ART. 138', '184684'),
    (1839, 'SUB-1839', 'SBM4', 'SI UN PARTICULAR SOLICITA COPIAS DE ACTUACIONES PROCESALES Y ACREDITA LEGÍTIMO INTERÉS, ¿QUÉ REQUISITO ADICIONAL DEBE CUMPLIRSE PARA QUE DICHA SOLICITUD SEA ESTIMADA CONFORME AL ARTÍCULO 138?', 'NO DEBE OBSTACULIZAR LA NORMAL PROSECUCIÓN DEL PROCESO NI AFECTAR DERECHOS FUNDAMENTALES DE TERCEROS', 'ART. 138', '184685'),
    (1840, 'SUB-1840', 'SBM4', 'EN EL CONTEXTO DEL ARTÍCULO 328 DEL NCPC, ¿QUÉ PROCEDIMIENTO DEBE SEGUIRSE SI EL DENUNCIANTE NO PUEDE FIRMAR UNA DENUNCIA ESCRITA O VERBAL?', 'SE LIMITARÁ A COLOCAR SU IMPRESIÓN DIGITAL, DEJÁNDOSE CONSTANCIA EN EL ACTA DEL IMPEDIMENTO', 'ART. 328', '184691'),
    (1841, 'SUB-1841', 'SBM4', 'EL JUEZ O FISCAL QUE CONOCE EN UN PROCESO QUE ANTERIORMENTE PATROCINÓ COMO ABOGADO, COMETE DELITO DE:.', 'PROHIBICIÓN DE CONOCER UN PROCESO QUE PATROCINÓ.', 'ART. 420', '183939'),
    (1842, 'SUB-1842', 'SBM4', 'EL MANDATARIO JUDICIAL O ABOGADO QUE, DESPUÉS DE HABER PATROCINADO O REPRESENTADO A UNA PARTE EN UN PROCESO JUDICIAL O ADMINISTRATIVO, ASUME LA DEFENSA DE LA PARTE CONTRARIA EN EL MISMO PROCESO, ESTA INCURSO EN EL DELITO DE:.', 'PATROCINIO INDEBIDO DE ABOGADO O MANDATARIO JUDICIAL.', 'ART. 421', '183940'),
    (1843, 'SUB-1843', 'SBM4', 'EL QUE INDEBIDAMENTE REVELA LA IDENTIDAD DE UN COLABORADOR EFICAZ, TESTIGO, AGRAVIADO O PERITO PROTEGIDO, AGENTE ENCUBIERTO O ESPECIAL, ASÍ COMO,BRINDE INFORMACIÓN QUE PERMITA SU IDENTIFICACIÓN, COMETE DELITO DE:.', 'REVELACIÓN INDEBIDA DE IDENTIDAD.', 'ART. 409 - B', '183941'),
    (1844, 'SUB-1844', 'SBM4', 'EL QUE, POR VIOLENCIA, AMENAZA O ASTUCIA, HACE EVADIR A UN PRESO, DETENIDO O INTERNO O LE PRESTA ASISTENCIA EN CUALQUIER FORMA PARA EVADIRSE, COMETE DELITO DE:.', 'FAVORECIMIENTO A LA FUGA.', 'ART. 414', '183942'),
    (1845, 'SUB-1845', 'SBM4', 'EL QUE OMITE COMUNICAR A LA AUTORIDAD LAS NOTICIAS QUE TENGA ACERCA DE LA COMISIÓN DE ALGÚN DELITO, CUANDO ESTE OBLIGADO A HACERLO POR SU PROFESIÓN O EMPLEO, COMETE DELITO DE:', 'OMISIÓN DE DENUNCIA.', 'ART. 407', '183943'),
    (1846, 'SUB-1846', 'SBM4', 'EL QUE PROMUEVE, FAVORECE, FINANCIA O FACILITA EL INGRESO O REINGRESO ILEGAL O EL TRÁNSITO IRREGULAR EN EL PAÍS DE OTRA PERSONA, CON EL FIN DE OBTENER DIRECTA O INDIRECTAMENTE, CUALQUIER BENEFICIO PARA SÍ O PARA TERCERO, COMETE DELITO DE:.', 'TRÁFICO ILÍCITO DE MIGRANTES.', 'ART. 303 - A', '183945'),
    (1847, 'SUB-1847', 'SBM4', 'EL QUE DAÑA, DESTRUYE O INUTILIZA UN BIEN, MUEBLE O INMUEBLE, TOTAL O PARCIALMENTE AJENO, COMETE DELITO DE:.', 'DAÑO SIMPLE.', 'ART. 205', '183946'),
    (1848, 'SUB-1848', 'SBM4', 'EL AUDITOR INTERNO O EXTERNO QUE A SABIENDAS DE LA EXISTENCIA DE DISTORSIONES O TERGIVERSACIONES SIGNIFICATIVAS EN LA INFORMACIÓN CONTABLE Y FINANCIERA DE LA PERSONA JURÍDICA NO LAS REVELA EN SU INFORME O DICTAMEN, COMETE DELITO DE:.', 'INFORMES DE AUDITORÍA DISTORSIONADOS.', 'ART. 198 - A', '183947'),
    (1849, 'SUB-1849', 'SBM4', 'EL QUE VIOLA LAS MEDIDAS IMPUESTAS POR LA LEY O POR LA AUTORIDAD PARA LA INTRODUCCIÓN AL PAÍS O LA PROPAGACIÓN DE UNA ENFERMEDAD O EPIDEMIA O UNA PLAGA, COMETE EL DELITO DE:', 'VIOLACIÓN DE MEDIDAS SANITARIAS.', 'ART. 292', '183949'),
    (1850, 'SUB-1850', 'SBM4', 'EL QUE, A SABIENDAS, MATA A SU ASCENDIENTE, DESCENDIENTE, NATURAL O ADOPTIVO, O A UNA PERSONA CON QUIEN SOSTIENE O HAYA SOSTENIDO UNA RELACIÓN CONYUGAL O DE CONVIVENCIA, CORRESPONDE A LA MODALIDAD DE:.', 'PARRICIDIO.', 'ART. 107', '183951'),
    (1851, 'SUB-1851', 'SBM4', 'EL QUE MATE A OTRO CONCURRIENDO CUALQUIERA DE LAS CIRCUNSTANCIAS SIGUIENTES:POR FEROCIDAD, CODICIA, LUCRO O PLACER, PARA FACILITAR U OCULTAR OTRO DELITO, CON GRAN CRUELDAD O ALEVOSÍA, POR FUEGO, EXPLOSIÓN U OTRO MEDIO CAPAZ DE PONER EN PELIGRO LA VIDA O SALUD DE OTRAS PERSONAS. ESTA CONSIDERADO COMO DELITO CONTRA LA VIDA, EL CUERPO Y LA SALUD EN LA MODALIDAD DE :.', 'HOMICIDIO CALIFICADO.', 'ART. 108', '183952'),
    (1852, 'SUB-1852', 'SBM4', 'EL QUE MATA A UNO DE LOS ALTOS FUNCIONARIOS COMPRENDIDOS EN EL ARTÍCULO 39 DE LA CONSTITUCIÓN POLÍTICA DEL PERÚ, A UN MIEMBRO DE LA POLICÍA NACIONAL, DE LAS FUERZAS ARMADAS, A UN MAGISTRADO DEL PODER JUDICIAL, O DEL MINISTERIO PÚBLICO, O A UN MIEMBRO DEL TRIBUNAL CONSTITUCIONAL O A CUALQUIER AUTORIDAD ELEGIDA POR MANDATO POPULAR EN EL EJERCICIO DE SUS FUNCIONES O COMO CONSECUENCIA DE ELLAS.- COMETE DELITO CONTRA LA VIDA, EL CUERPO Y LA SALUD, EN LA MODALIDAD :.', 'HOMICIDIO CALIFICADO POR LA CONDICIÓN DE LA VÍCTIMA.', 'ART. 108 - A', '183953'),
    (1853, 'SUB-1853', 'SBM4', 'EL QUE, EN EL CONTEXTO DE VIOLENCIA FAMILIAR, COACCIÓN, HOSTIGAMIENTO O ACOSO, ABUSO DE PODER, CONFIANZA O DE CUALQUIER OTRA POSICIÓN O RELACIÓN QUE LE CONFIERA AUTORIDAD AL AGENTE, MATA A UNA MUJER POR SU CONDICIÓN DE TAL, COMETE DELITO CONTRA LA VIDA, EL CUERPO Y LA SALUD, EN LA MODALIDAD DE:.', 'FEMINICIDIO.', 'ART. 108 - B', '183954'),
    (1854, 'SUB-1854', 'SBM4', 'EN EL DELITO DE FEMINICIDIO, LA PENA SERÁ DE CADENA PERPETUA, CUANDO CONCURRAN CIRCUNSTANCIAS AGRAVANTES EN CANTIDAD DE :.', 'DOS O MÁS CIRCUNSTANCIAS AGRAVANTES.', 'ART. 108 - B', '183955'),
    (1855, 'SUB-1855', 'SBM4', 'EL QUE MATA A OTRO POR ORDEN, ENCARGO O ACUERDO, CON EL PROPÓSITO DE OBTENER PARA SÍ O PARA OTRO UN BENEFICIO ECONÓMICO O DE CUALQUIER OTRA ÍNDOLE. CORRESPONDE A LA COMISIÓN DE DELITO CONTRA LA VIDA, EL CUERPO Y LA SALUD, EN LA MODALIDAD DE :.', 'SICARIATO.', 'ART. 108 - C', '183956'),
    (1856, 'SUB-1856', 'SBM4', 'QUIEN PARTICIPA EN UNA CONSPIRACIÓN PARA PROMOVER, FAVORECER O FACILITAR EL DELITO DE SICARIATO Y QUIEN SOLICITA U OFRECE A OTROS, COMETER EL DELITO DE SICARIATO O ACTÚA COMO INTERMEDIARIO, SE ENCUENTRA INCURSO EN:.', 'CONSPIRACIÓN Y OFRECIMIENTO PARA EL DELITO DE SICARIATO.', 'ART. 108 - D', '183957'),
    (1857, 'SUB-1857', 'SBM4', 'LA MADRE QUE MATA A SU HIJO DURANTE EL PARTO O BAJO LA INFLUENCIA DEL ESTADO PUERPERAL. INCURRE EN DELITO CONTRA LA VIDA, EL CUERPO Y LA SALUD; EN LA MODALIDAD DE:. Código Penal', 'INFANTICIDIO.', 'ART. 110', '183959'),
    (1858, 'SUB-1858', 'SBM4', 'EL QUE, POR PIEDAD, MATA A UN ENFERMO INCURABLE QUE LE SOLICITA DE MANERA EXPRESA Y CONSCIENTE PARA PONER FIN A SUS INTOLERABLES DOLORES. INCURRE EN DELITO CONTRA LA VIDA, EL CUERPO Y LA SALUD, EN LA MODALIDAD DE :.', 'HOMICIDIO PIADOSO.', 'ART. 112', '183961'),
    (1859, 'SUB-1859', 'SBM4', 'EL QUE INSTIGA A OTRO AL SUICIDIO O LO AYUDA A COMETERLO, SERÁ REPRIMIDO, SI EL SUICIDIO SE HA CONSUMADO O INTENTADO. ESTAMOS REFIRIÉNDONOS AL DELITO CONTRA LA VIDA, EL CUERPO Y LA SALUD, EN LA MODALIDAD DE :.', 'INSTIGACIÓN O AYUDA AL SUICIDIO.', 'ART. 113', '183962'),
    (1860, 'SUB-1860', 'SBM4', 'LA MUJER QUE CAUSA SU ABORTO, O CONSIENTE QUE OTRO LE PRACTIQUE, CORRESPONDE A LA DEFINICIÓN DE:.', 'AUTOABORTO.', 'ART. 114', '183963'),
    (1861, 'SUB-1861', 'SBM4', 'EL QUE HACE ABORTAR A UNA MUJER SIN SU CONSENTIMIENTO, CORRESPONDE A LA DEFINICIÓN DE:.', 'ABORTO SIN CONSENTIMIENTO.', 'ART. 116', '183965'),
    (1862, 'SUB-1862', 'SBM4', 'EL QUE, CON VIOLENCIA, OCASIONA UN ABORTO, SIN HABER TENIDO EL PROPÓSITO DE CAUSARLO, SIENDO NOTORIO O CONSTÁNDOLE EL EMBARAZO, COMETE DELITO DE:.', 'ABORTO PRETERINTENCIONAL.', 'ART. 118', '183966'),
    (1863, 'SUB-1863', 'SBM4', 'NO ES PUNIBLE EL ABORTO PRACTICADO POR UN MÉDICO CON EL CONSENTIMIENTO DE LA MUJER EMBARAZADA O DE SU REPRESENTANTE LEGAL, SI LO TUVIERE, CUANDO ES EL ÚNICO MEDIO PARA SALVAR LA VIDA DE LA GESTANTE O PARA EVITAR EN SU SALUD UN MAL GRAVE Y PERMANENTE, ESTE ENUNCIADO CORRESPONDE A:.', 'ABORTO TERAPÉUTICO.', 'ART. 119', '183967'),
    (1864, 'SUB-1864', 'SBM4', 'EL QUE CAUSA A OTRO DAÑO GRAVE EN EL CUERPO O EN LA SALUD FÍSICA Y MENTAL Y PONE EN PELIGRO INMINENTE LA VIDA DE LA VÍCTIMA, COMETE DELITO DE:', 'LESIONES GRAVES.', 'ART. 121', '183969'),
    (1865, 'SUB-1865', 'SBM4', 'EL QUE CAUSA A OTRO DAÑO GRAVE EN EL CUERPO O EN LA SALUD FISICA O MENTAL, Y LA VÍCTIMA ES MENOR DE EDAD, ADULTA MAYOR O TIENE DISCAPACIDAD Y EL AGENTE SE APROVECHA DE DICHA CONDICIÓN, COMETE DELITO DE:.', 'LESIONES GRAVES.', 'ART. 121', '183970'),
    (1866, 'SUB-1866', 'SBM4', 'EL QUE CAUSA A OTRO LESIONES EN EL CUERPO O EN LA SALUD FISICA Y MENTAL QUE REQUIERA MÁS DE DIEZ Y MENOS DE VEINTE DÍAS DE ASISTENCIA O DESCANSO, SEGÚN PRESCRIPCIÓN FACULTATIVA, O NIVEL MODERADO DE DAÑO PSIQUICO. ESTE ENUNCIADO SE REFIERE A:.', 'LESIONES LEVES.', 'ART. 122', '183971'),
    (1867, 'SUB-1867', 'SBM4', 'CUANDO EL AGENTE PRODUZCA UN RESULTADO GRAVE QUE NO QUISO CAUSAR, NI PUDO PREVER, LA PENA SERÁ DISMINUIDA PRUDENCIALMENTE HASTA LA QUE CORRESPONDA A LA LESIÓN QUE QUISO INFERIR, CORRESPONDE A:.', 'LESIONES PRETERINTENCIONALES CON RESULTADO FORTUITO.', 'ART. 123', '183972'),
    (1868, 'SUB-1868', 'SBM4', 'EL QUE POR CULPA CAUSA A OTRO UN DAÑO EN EL CUERPO O EN LA SALUD, SERÁ REPRIMIDO POR ACCIÓN PRIVADA, CON PENA PRIVATIVA DE LIBERTAD NO MAYOR DE UN AÑO Y CON SESENTA A CIENTO VEINTE DÍAS- MULTA, COMETE DELITO DE:.', 'LESIONES CULPOSAS.', 'ART. 124', '183973'),
    (1869, 'SUB-1869', 'SBM4', 'EL QUE EXPONE A PELIGRO DE MUERTE O DE GRAVE E INMINENTE DAÑO A LA SALUD O ABANDONA EN IGUALES CIRCUNSTANCIAS A UN MENOR DE EDAD O A UNA PERSONA INCAPAZ DE VALERSE POR SÍ MISMA QUE ESTÉN LEGALMENTE BAJO SU PROTECCIÓN O QUE SE HALLEN DE HECHO BAJO SU CUIDADO, COMETE DELITO DE:.', 'EXPOSICIÓN O ABANDONO PELIGROSOS.', 'ART. 125', '183975'),
    (1870, 'SUB-1870', 'SBM4', 'EL QUE ENCUENTRA A UN HERIDO O A CUALQUIER OTRA PERSONA EN ESTADO DE GRAVE E INMINENTE PELIGRO Y OMITE PRESTARLE AUXILIO INMEDIATO PUDIENDO HACERLO SIN RIESGO PROPIO O DE TERCERO O SE ABSTIENE DE DAR AVISO A LA AUTORIDAD, COMETE DELITO DE:.', 'OMISIÓN DE AUXILIO O AVISO A LA AUTORIDAD.', 'ART. 127', '183977'),
    (1871, 'SUB-1871', 'SBM4', 'EL QUE EXPONE A PELIGRO LA VIDA O LA SALUD DE UNA PERSONA COLOCADA BAJO SU AUTORIDAD, DEPENDENCIA, TUTELA, CURATELA O VIGILANCIA, SEA PRIVÁNDOLA DE ALIMENTOS O CUIDADOS INDISPENSABLES, SEA ABUSANDO DE LOS MEDIOS DE CORRECCIÓN O DISCIPLINA, O CUALQUIER ACTO ANÁLOGO, COMETE DELITO DE:.', 'EXPOSICIÓN A PELIGRO DE PERSONA DEPENDIENTE.', 'ART. 128', '183978'),
    (1872, 'SUB-1872', 'SBM4', 'EL QUE, MEDIANTE AMENAZA O VIOLENCIA, OBLIGA A OTRO A HACER LO QUE LA LEY NO MANDA O LE IMPIDE HACER LO QUE ELLA NO PROHIBE. COMETE DELITO DE:.', 'COACCIÓN.', 'ART. 151', '183979'),
    (1873, 'SUB-1873', 'SBM4', 'EL QUE, SIN DERECHO, MOTIVO NI FACULTAD JUSTIFICADA, PRIVA A OTRO DE SU LIBERTAD PERSONAL, CUALQUIERA SEA EL MÓVIL, EL PROPÓSITO, LA MODALIDAD O CIRCUNSTANCIA O TIEMPO QUE EL AGRAVIADO SUFRA LA PRIVACIÓN O RESTRICCIÓN DE SU LIBERTAD, COMETE DELITO DE:.', 'SECUESTRO.', 'ART. 152', '183980'),
    (1874, 'SUB-1874', 'SBM4', 'EL QUE VIOLA LA VIDA PERSONAL O FAMILIAR YA SEA OBSERVANDO, ESCUCHANDO O REGISTRANDO UN HECHO. COMETE DELITO DE:.', 'VIOLACIÓN DE LA INTIMIDAD.', 'ART. 154', '183982'),
    (1875, 'SUB-1875', 'SBM4', 'EL QUE ILEGÍTIMAMENTE COMERCIALIZA O VENDE INFORMACIÓN NO PÚBLICA RELATIVA A CUALQUIER ÁMBITO DE LA ESFERA PERSONAL, FAMILIAR, PATRIMONIAL, LABORAL, FINANCIERA U OTRO DE NATURALEZA ANÁLOGA SOBRE UNA PERSONA NATURAL, COMETE DELITO DE:.', 'TRÁFICO ILEGAL DE DATOS PERSONALES.', 'ART. 154 - A', '183983'),
    (1876, 'SUB-1876', 'SBM4', 'EL QUE REVELA ASPECTOS DE LA INTIMIDAD PERSONAL O FAMILIAR QUE CONOCIERA CON MOTIVO DEL TRABAJO QUE PRESTÓ AL AGRAVIADO O A LA PERSONA A QUIEN ÉSTE SE LO CONFIÓ. COMETE DELITO DE :.', 'REVELACIÓN DE LA INTIMIDAD PERSONAL Y FAMILIAR.', 'ART. 156', '183984'),
    (1877, 'SUB-1877', 'SBM4', 'EL QUE, INDEBIDAMENTE, ORGANIZA, PROPORCIONA O EMPLEA CUALQUIER ARCHIVO QUE TENGA DATOS REFERENTES A LAS CONVICCIONES POLÍTICAS O RELIGIOSAS Y OTROS ASPECTOS DE LA VIDA ÍNTIMA DE UNA O MÁS PERSONAS. COMETE DELITO DE:.', 'USO INDEBIDO DE ARCHIVOS COMPUTARIZADOS.', 'ART. 157', '183985'),
    (1878, 'SUB-1878', 'SBM4', 'EL QUE, SIN DERECHO, PENETRA EN MORADA O CASA DE NEGOCIO AJENA, EN SU DEPENDENCIA O EN EL RECINTO HABITADO POR OTRO O EL QUE PERMANECE ALLÍ REHUSANDO LA INTIMACIÓN QUE LE HAGA QUIEN TENGA DERECHO A FORMULARLA, COMETE DELITO DE:.', 'VIOLACIÓN DE DOMICILIO.', 'ART. 159', '183987'),
    (1879, 'SUB-1879', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PÚBLICO QUE ALLANA UN DOMICILIO, SIN LAS FORMALIDADES PRESCRITAS POR LA LEY O FUERA DE LOS CASOS QUE ELLA DETERMINA, COMETE DELITO DE:. Código Penal', 'ALLANAMIENTO ILEGAL DE DOMICILIO.', 'ART. 160', '183988'),
    (1880, 'SUB-1880', 'SBM4', 'EL QUE ABRE, INDEBIDAMENTE, UNA CARTA, UN PLIEGO, TELEGRAMA, RADIOGRAMA, DESPACHO TELEFÓNICO U OTRO DOCUMENTO DE NATURALEZA ANÁLOGA, QUE NO LE ESTÉ DIRIGIDO, O SE APODERA INDEBIDAMENTE DE ALGUNO DE ESTOS DOCUMENTOS, AUNQUE NO ESTÉ CERRADO, COMETE DELITO DE:.', 'VIOLACIÓN DE CORRESPONDENCIA.', 'ART. 161', '183989'),
    (1881, 'SUB-1881', 'SBM4', 'EL QUE FABRICA, ADQUIERE, INTRODUCE AL TERRITORIO NACIONAL, POSEE O COMERCIALIZA EQUIPOS O SOFTWARES DESTINADOS A INTERCEPTAR ILEGALMENTE LAS COMUNICACIONES O SIMILARES, COMETE DELITO DE:.', 'POSESIÓN O COMERCIALIZACIÓN DE EQUIPOS DESTINADOS A LA INTERCEPTACIÓN TELEFÓNICA O SIMILAR.', 'ART. 162 - A', '183991'),
    (1882, 'SUB-1882', 'SBM4', 'EL QUE PUBLICA, INDEBIDAMENTE, UNA CORRESPONDENCIA EPISTOLAR O TELEGRÁFICA, NO DESTINADA A LA PUBLICIDAD, AUNQUE LE HAYA SIDO DIRIGIDA, SERÁ REPRIMIDO, SI EL HECHO CAUSA ALGÚN PERJUICIO A OTRO, COMETE DELITO DE:.', 'PUBLICACIÓN INDEBIDA DE CORRESPONDENCIA', 'ART. 164', '183992'),
    (1883, 'SUB-1883', 'SBM4', 'EL QUE, TENIENDO INFORMACIÓN POR RAZÓN DE SU ESTADO, OFICIO, EMPLEO, PROFESIÓN O MINISTERIO, DE SECRETOS CUYA PUBLICACIÓN PUEDA CAUSAR DAÑO, LOS REVELA SIN CONSENTIMIENTO DEL INTERESADO, COMETE DELITO DE:.', 'VIOLACIÓN DEL SECRETO PROFESIONAL.', 'ART. 165', '183993'),
    (1884, 'SUB-1884', 'SBM4', 'EN EL DELITO DE VIOLACIÓN DE LA LIBERTAD DE REUNIÓN, EL FUNCIONARIO PÚBLICO QUE ABUSANDO DE SU CARGO NO AUTORIZA, NO GARANTIZA, PROHÍBE O IMPIDE UNA REUNIÓN PÚBLICA, LÍCITAMENTE CONVOCADA, COMETE DELITO DE:.', 'PROHIBICIÓN DE REUNIÓN PÚBLICA LÍCITA POR FUNCIONARIO PÚBLICO.', 'ART. 167', '183995'),
    (1885, 'SUB-1885', 'SBM4', 'EL FUNCIONARIO PÚBLICO QUE, ABUSANDO DE SU CARGO, SUSPENDE O CLAUSURA ALGÚN MEDIO DE COMUNICACIÓN SOCIAL O IMPIDE SU CIRCULACIÓN O DIFUSIÓN, COMETE DELITO DE:.', 'VIOLACIÓN DE LA LIBERTAD DE EXPRESIÓN.', 'ART. 169', '183997'),
    (1886, 'SUB-1886', 'SBM4', 'EL QUE CON VIOLENCIA, FÍSICA O PSICOLÓGICA, GRAVE AMENAZA O APROVECHÁNDOSE DE UN ENTORNO DE COACCIÓN O DE CUALQUIER OTRO ENTORNO QUE IMPIDA A LA PERSONA DAR SU LIBRE CONSENTIMIENTO, OBLIGA A ESTA A TENER ACCESO CARNAL POR VÍA VAGINAL, ANAL O BUCAL O REALIZA CUALQUIER OTRO ACTO ANÁLOGO CON LA INTRODUCCIÓN DE UN OBJETO O PARTE DEL CUERPO POR ALGUNA DE LAS DOS PRIMERAS VÍAS, COMETE DELITO DE:', 'VIOLACIÓN SEXUAL.', 'ART. 170', '183998'),
    (1887, 'SUB-1887', 'SBM4', 'EL QUE TIENE ACCESO CARNAL CON UNA PERSONA POR VÍA VAGINAL, ANAL O BUCAL, O REALIZA CUALQUIER OTRO ACTO ANÁLOGO CON LA INTRODUCCIÓN DE UN OBJETO O PARTE DEL CUERPO POR ALGUNA DE LAS DOS PRIMERAS VÍAS, DESPUÉS DE HABERLA PUESTO EN ESTADO DE INCONSCIENCIA O EN LA IMPOSIBILIDAD DE RESISTIR, COMETE DELITO DE:', 'VIOLACIÓN DE PERSONA EN ESTADO DE INCONSCIENCIA O EN LA IMPOSIBILIDAD DE RESISTIR', 'ART. 171', '183999'),
    (1888, 'SUB-1888', 'SBM4', 'EL QUE TIENE ACCESO CARNAL POR VÍA VAGINAL, ANAL O BUCAL O REALIZA CUALQUIER OTRO ACTO ANÁLOGO CON LA INTRODUCCIÓN DE UN OBJETO O PARTE DEL CUERPO POR ALGUNA DE LAS DOS PRIMERAS VÍAS, CON UN MENOR, COMETE DELITO DE:', 'VIOLACIÓN SEXUAL DE MENOR DE EDAD.', 'ART. 173', '184001'),
    (1889, 'SUB-1889', 'SBM4', 'EL QUE EMPLEE, DESARROLLE, PRODUZCA, ADQUIERA, ALMACENE, CONSERVE O TRANSFIERA A UNA PERSONA NATURAL O JURÍDICA, MINAS ANTIPERSONALES, COMETE DELITO DE:', 'EMPLEO, PRODUCCIÓN Y TRANSFERENCIA DE MINAS ANTIPERSONALES.', 'ART. 279 - D Código Penal', '184002'),
    (1890, 'SUB-1890', 'SBM4', 'EL QUE SIN CUMPLIR CON LA NORMATIVIDAD VIGENTE Y/O SIN CONTAR CON LA AUTORIZACIÓN EXPRESA, QUE PARA EL EFECTO EXPIDA LA AUTORIDAD COMPETENTE, REALICE U ORDENE REALIZAR A SUS SUBORDINADOS LA ACTIVIDAD DE ENSAMBLADO DE ÓMNIBUS SOBRE CHASIS ORIGINALMENTE DISEÑADO Y FABRICADO PARA EL TRANSPORTE DE MERCANCÍAS CON CORTE O ALARGAMIENTO DEL CHASIS; COMETE DELITO DE:', 'ENSAMBLADO, COMERCIALIZACIÓN Y UTILIZACIÓN, EN EL SERVICIO PÚBLICO, DE TRANSPORTE DE OMNIBUSES SOBRE CHASIS DE CAMIÓN.', 'ART. 279 - E', '184003'),
    (1891, 'SUB-1891', 'SBM4', 'EL QUE, SIN ESTAR DEBIDAMENTE AUTORIZADO, FABRICA, ENSAMBLA, MODIFICA, ALMACENA, SUMINISTRA, COMERCIALIZA, TRAFICA, USA, PORTA O TIENE EN SU PODER, ARMAS DE FUEGO DE CUALQUIER TIPO, MUNICIONES, ACCESORIOS O MATERIALES DESTINADOS PARA SU FABRICACIÓN O MODIFICACIÓN, COMETE DELITO DE:.', 'FABRICACIÓN, COMERCIALIZACIÓN, USO O PORTE DE ARMAS.', 'ART. 279 - G', '184005'),
    (1892, 'SUB-1892', 'SBM4', 'EL QUE CONTACTA CON UN MENOR DE CATORCE AÑOS PARA SOLICITAR U OBTENER DE ÉL MATERIAL PORNOGRÁFICO, O PARA PROPONERLE LLEVAR A CABO CUALQUIER ACTO DE CONNOTACION SEXUAL CON ÉL O CON TERCEROS, COMETE DELITO DE:.', 'PROPOSICIONES A NIÑOS, NIÑAS Y ADOLESCENTES CON FINES SEXUALES', 'ART. 183 - B', '184007'),
    (1893, 'SUB-1893', 'SBM4', 'EXCUSA ABSOLUTORIA. EXENCIÓN DE PENA: NO SON REPRIMIBLES, SIN PERJUICIO DE LA REPARACIÓN CIVIL, LOS HURTOS, APROPIACIONES, DEFRAUDACIONES O DAÑOS QUE SE CAUSEN:', 'LOS CÓNYUGES, CONCUBINOS, ASCENDIENTES, DESCENDIENTES Y AFINES EN LÍNEA RECTA.', 'ART. 208', '184009'),
    (1894, 'SUB-1894', 'SBM4', '. EL MÉDICO, OBSTETRA, FARMACÉUTICO O CUALQUIER PROFESIONAL SANITARIO QUE ABUSA DE SU CIENCIA O ARTE PARA CAUSAR EL ABORTO, SE LE CONSIDERARÁ:', 'AGRAVACIÓN DE LA PENA POR LA CALIDAD DEL SUJETO.', 'ART. 117', '184010'),
    (1895, 'SUB-1895', 'SBM4', 'EL QUE, SIN TÍTULO O NOMBRAMIENTO, USURPA UNA FUNCIÓN PÚBLICA, O LA FACULTAD DE DAR ÓRDENES MILITARES O POLICIALES, O EL QUE HALLÁNDOSE DESTITUIDO, CESADO, SUSPENDIDO O SUBROGADO DE SU CARGO CONTINÚA EJERCIÉNDOLO, O EL QUE EJERCE FUNCIONES CORRESPONDIENTES A CARGO DIFERENTE DEL QUE TIENE, COMETE DELITO DE:.', 'USURPACIÓN DE FUNCIÓN PÚBLICA.', 'ART. 361', '184011'),
    (1896, 'SUB-1896', 'SBM4', 'EL QUE EJERCE PROFESIÓN SIN REUNIR LOS REQUISITOS LEGALES REQUERIDOS, COMETE DELITO DE:.', 'EJERCICIO ILEGAL DE PROFESIÓN.', 'ART. 363', '184012'),
    (1897, 'SUB-1897', 'SBM4', 'EL QUE, CON LA INTENCIÓN DE DESTRUIR, TOTAL O PARCIALMENTE, A UN GRUPO NACIONAL, ÉTNICO, SOCIAL O RELIGIOSO, REALIZA: TRANSFERENCIA FORZADA DE NIÑOS A OTRO GRUPO, COMETE DELITO DE:.', 'GENOCIDIO.', 'ART. 319', '184013'),
    (1898, 'SUB-1898', 'SBM4', 'EL QUE, PÚBLICAMENTE, OSTENTA INSIGNIAS O DISTINTIVOS DE UNA FUNCIÓN O CARGO QUE NO EJERCE O SE ARROGA GRADO ACADÉMICO, TÍTULO PROFESIONAL U HONORES QUE NO LE CORRESPONDEN, COMETE DELITO DE:.', 'OSTENTACIÓN DE DISTINTIVOS DE FUNCIÓN O CARGOS QUE NO EJERCE.', 'ART. 362', '184014'),
    (1899, 'SUB-1899', 'SBM4', 'EL QUE, SIN ALZAMIENTO PÚBLICO, MEDIANTE VIOLENCIA O AMENAZA, IMPIDE A UNA AUTORIDAD O A UN FUNCIONARIO O SERVIDOR PÚBLICO EJERCER SUS FUNCIONES O LE OBLIGA A PRACTICAR UN DETERMINADO ACTO DE SUS FUNCIONES O LE ESTORBA EN EL EJERCICIO DE ÉSTAS, COMETE DELITO DE:.', 'VIOLENCIA CONTRA LA AUTORIDAD PARA OBLIGARLE A ALGO.', 'ART. 365', '184016'),
    (1900, 'SUB-1900', 'SBM4', 'EL PROFESIONAL QUE AMPARA CON SU FIRMA EL TRABAJO DE QUIEN NO TIENE TÍTULO PARA EJERCERLO, COMETE DELITO DE:.', 'PARTICIPACIÓN EN EJERCICIO ILEGAL DE LA PROFESIÓN.', 'ART. 364', '184017')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

