INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 1901 a 2000
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (1901, 'SUB-1901', 'SBM4', 'EL QUE, CON LA INTENCIÓN DE DESTRUIR, TOTAL O PARCIALMENTE, A UN GRUPO ÉTNICO REALIZA, MATANZA DE MIEMBROS DEL GRUPO, COMETE DELITO DE:.', 'GENOCIDIO.', 'ART. 319', '184018'),
    (1902, 'SUB-1902', 'SBM4', 'EL QUE EMPLEA INTIMIDACIÓN O VIOLENCIA CONTRA UN FUNCIONARIO PÚBLICO O CONTRA LA PERSONA QUE LE PRESTA ASISTENCIA EN VIRTUD DE UN DEBER LEGAL O ANTE REQUERIMIENTO DE AQUÉL, PARA IMPEDIR O TRABAR LA EJECUCIÓN DE UN ACTO PROPIO DE LEGÍTIMO EJERCICIO DE SUS FUNCIONES, COMETE DELITO DE::.', 'VIOLENCIA CONTRA LA AUTORIDAD PARA IMPEDIR EL EJERCICIO DE SUS FUNCIONES.', 'ART. 366', '184019'),
    (1903, 'SUB-1903', 'SBM4', 'UNA DE LAS FORMAS AGRAVADAS DE LOS DELITOS DE VIOLENCIA Y RESISTENCIA A LA AUTORIDAD (VIOLENCIA CONTRA LA AUTORIDAD PARA OBLIGARLE A ALGO Y VIOLENCIA CONTRA LA AUTORIDAD PARA IMPEDIR EL EJERCICIO DE SUS FUNCIONES), ES CUANDO:.', 'EL HECHO SE REALIZA POR DOS O MÁS PERSONAS.', 'ART. 367', '184021'),
    (1904, 'SUB-1904', 'SBM4', 'UNA DE LAS FORMAS AGRAVADAS DE LOS DELITOS DE VIOLENCIA Y RESISTENCIA A LA AUTORIDAD (VIOLENCIA CONTRA LA AUTORIDAD PARA OBLIGARLE A ALGO Y VIOLENCIA CONTRA LA AUTORIDAD PARA IMPEDIR EL EJERCICIO DE SUS FUNCIONES), ES CUANDO:.', 'EL AUTOR ES FUNCIONARIO O SERVIDOR PÚBLICO.', 'ART. 367', '184022'),
    (1905, 'SUB-1905', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PÚBLICO, O CUALQUIER PERSONA CON EL CONSENTIMIENTO O AQUIESCENCIA DE AQUEL, QUE DE CUALQUIER FORMA PRIVA A OTRO DE SU LIBERTAD Y SE HAYA NEGADO A RECONOCER DICHA PRIVACIÓN DE LIBERTAD O A DAR INFORMACIÓN CIERTA SOBRE EL DESTINO O EL PARADERO DE LA VÍCTIMA; COMETE DELITO DE:', 'DESAPARICIÓN FORZADA DE PERSONAS.', 'ART. 320', '184024'),
    (1906, 'SUB-1906', 'SBM4', 'UNA DE LAS FORMAS AGRAVADAS DE LOS DELITOS DE VIOLENCIA Y RESISTENCIA A LA AUTORIDAD (VIOLENCIA CONTRA LA AUTORIDAD PARA OBLIGARLE A ALGO Y VIOLENCIA CONTRA LA AUTORIDAD PARA IMPEDIR EL EJERCICIO DE SUS FUNCIONES), ES CUANDO:.', 'EL AUTOR CAUSA UNA LESIÓN GRAVE QUE HAYA PODIDO PREVER.', 'ART. 367', '184025'),
    (1907, 'SUB-1907', 'SBM4', 'UNA DE LAS FORMAS AGRAVADAS DE LOS DELITOS DE VIOLENCIA Y RESISTENCIA A LA AUTORIDAD (VIOLENCIA CONTRA LA AUTORIDAD PARA OBLIGARLE A ALGO Y VIOLENCIA CONTRA LA AUTORIDAD PARA IMPEDIR EL EJERCICIO DE SUS FUNCIONES), ES CUANDO:.', 'EL HECHO SE REALIZA EN CONTRA DE UN MAGISTRADO DEL PODER JUDICIAL.', 'ART. 367', '184027'),
    (1908, 'SUB-1908', 'SBM4', 'UNA DE LAS FORMAS AGRAVADAS DE LOS DELITOS DE VIOLENCIA Y RESISTENCIA A LA AUTORIDAD (VIOLENCIA CONTRA LA AUTORIDAD PARA OBLIGARLE A ALGO Y VIOLENCIA CONTRA LA AUTORIDAD PARA IMPEDIR EL EJERCICIO DE SUS FUNCIONES), ES CUANDO:.', 'EL HECHO SE REALIZA EN CONTRA DE UN MAGISTRADO DEL MINISTERIO PÚBLICO.', 'ART. 367', '184028'),
    (1909, 'SUB-1909', 'SBM4', 'UNA DE LAS FORMAS AGRAVADAS DE LOS DELITOS DE VIOLENCIA Y RESISTENCIA A LA AUTORIDAD (VIOLENCIA CONTRA LA AUTORIDAD PARA OBLIGARLE A ALGO Y VIOLENCIA CONTRA LA AUTORIDAD PARA IMPEDIR EL EJERCICIO DE SUS FUNCIONES), ES CUANDO:.', 'EL HECHO SE REALIZA EN CONTRA DE UN MIEMBRO DEL TRIBUNAL CONSTITUCIONAL.', 'ART. 367', '184030'),
    (1910, 'SUB-1910', 'SBM4', 'UNA DE LAS FORMAS AGRAVADAS DE LOS DELITOS DE VIOLENCIA Y RESISTENCIA A LA AUTORIDAD (VIOLENCIA CONTRA LA AUTORIDAD PARA OBLIGARLE A ALGO Y VIOLENCIA CONTRA LA AUTORIDAD PARA IMPEDIR EL EJERCICIO DE SUS FUNCIONES), ES CUANDO:.', 'EL HECHO SE REALIZA EN CONTRA DE UNA AUTORIDAD ELEGIDA POR MANDATO POPULAR, EN EL EJERCICIO DE SUS FUNCIONES.', 'ART. 367', '184031'),
    (1911, 'SUB-1911', 'SBM4', 'ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE DESAPARICIÓN FORZADA DE PERSONAS, SI LA VÍCTIMA:.', 'SE ENCUENTRA EN ESTADO DE GESTACIÓN.', 'ART. 320', '184032'),
    (1912, 'SUB-1912', 'SBM4', 'UNA DE LAS FORMAS AGRAVADAS DE LOS DELITOS DE VIOLENCIA Y RESISTENCIA A LA AUTORIDAD (VIOLENCIA CONTRA LA AUTORIDAD PARA OBLIGARLE A ALGO Y VIOLENCIA CONTRA LA AUTORIDAD PARA IMPEDIR EL EJERCICIO DE SUS FUNCIONES), ES CUANDO:', 'EL HECHO SE REALIZA PARA IMPEDIR LA ERRADICACIÓN O DESTRUCCIÓN DE CULTIVOS ILEGALES.', 'ART. 367', '184033'),
    (1913, 'SUB-1913', 'SBM4', 'ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE DESAPARICIÓN FORZADA DE PERSONAS, SI LA VÍCTIMA:.', 'PADECE DE CUALQUIER TIPO DE DISCAPACIDAD.', 'ART. 320', '184034'),
    (1914, 'SUB-1914', 'SBM4', 'UNA DE LAS FORMAS AGRAVADAS DE LOS DELITOS DE VIOLENCIA Y RESISTENCIA A LA AUTORIDAD (VIOLENCIA CONTRA LA AUTORIDAD PARA OBLIGARLE A ALGO Y VIOLENCIA CONTRA LA AUTORIDAD PARA IMPEDIR EL EJERCICIO DE SUS FUNCIONES), ES CUANDO:.', 'EL HECHO SE COMETE RESPECTO A INVESTIGACIONES O JUZGAMIENTO POR LOS DELITOS DE TERRORISMO.', 'ART. 367', '184035'),
    (1915, 'SUB-1915', 'SBM4', 'UNA DE LAS FORMAS AGRAVADAS DE LOS DELITOS DE VIOLENCIA Y RESISTENCIA A LA AUTORIDAD (VIOLENCIA CONTRA LA AUTORIDAD PARA OBLIGARLE A ALGO Y VIOLENCIA CONTRA LA AUTORIDAD PARA IMPEDIR EL EJERCICIO DE SUS FUNCIONES), ES CUANDO:.', 'EL HECHO SE COMETE RESPECTO A INVESTIGACIONES O JUZGAMIENTO POR LOS DELITOS DE TERRORISMO, TRÁFICO ILÍCITO DE DROGAS.', 'ART. 367', '184037'),
    (1916, 'SUB-1916', 'SBM4', 'UNA DE LAS FORMAS AGRAVADAS DE LOS DELITOS DE VIOLENCIA Y RESISTENCIA A LA AUTORIDAD (VIOLENCIA CONTRA LA AUTORIDAD PARA OBLIGARLE A ALGO Y VIOLENCIA CONTRA LA AUTORIDAD PARA IMPEDIR EL EJERCICIO DE SUS FUNCIONES), ES CUANDO:. Código Penal', 'EL HECHO SE COMETE RESPECTO A INVESTIGACIONES O JUZGAMIENTO POR LOS DELITOS DE LAVADO DE ACTIVOS.', 'ART. 367', '184038'),
    (1917, 'SUB-1917', 'SBM4', 'FORMAS AGRAVADAS DE LOS DELITOS DE VIOLENCIA CONTRA LA AUTORIDAD PARA OBLIGARLE A ALGO Y VIOLENCIA CONTRA LA AUTORIDAD PARA IMPEDIR EL EJERCICIO DE SUS FUNCIONES, ES CUANDO:.', 'EL HECHO SE COMETE RESPECTO A INVESTIGACIONES O JUZGAMIENTO POR LOS DELITOS DE EXTORSIÓN.', 'ART. 367', '184040'),
    (1918, 'SUB-1918', 'SBM4', 'UNA DE LAS FORMAS AGRAVADAS DE LOS DELITOS DE VIOLENCIA Y RESISTENCIA A LA AUTORIDAD (VIOLENCIA CONTRA LA AUTORIDAD PARA OBLIGARLE A ALGO Y VIOLENCIA CONTRA LA AUTORIDAD PARA IMPEDIR EL EJERCICIO DE SUS FUNCIONES), ES CUANDO:.', 'EL HECHO SE COMETE RESPECTO A INVESTIGACIONES O JUZGAMIENTO POR LOS DELITOS DE TRATA DE PERSONAS.', 'ART. 367', '184041'),
    (1919, 'SUB-1919', 'SBM4', 'EL QUE DESOBEDECE O RESISTE LA ORDEN LEGALMENTE IMPARTIDA POR UN FUNCIONARIO PÚBLICO EN EL EJERCICIO DE SUS ATRIBUCIONES, SALVO QUE SE TRATE DE LA PROPIA DETENCIÓN, COMETE DELITO DE:.', 'RESISTENCIA O DESOBEDIENCIA A LA AUTORIDAD.', 'ART. 368', '184042'),
    (1920, 'SUB-1920', 'SBM4', 'CUANDO SE DESOBEDEZCA LA ORDEN DE REALIZARSE UN ANÁLISIS DE SANGRE O DE OTROS FLUIDOS CORPORALES QUE TENGA POR FINALIDAD DETERMINAR EL NIVEL, PORCENTAJE O INGESTA DE ALCOHOL, DROGAS TÓXICAS ESTUPEFACIENTES, SUSTANCIAS PSICOTRÓPICAS O SINTÉTICAS, SE COMETE DELITO:.', 'RESISTENCIA O DESOBEDIENCIA A LA AUTORIDAD.', 'ART. 368', '184044'),
    (1921, 'SUB-1921', 'SBM4', 'ES UNA MODALIDAD DELICTIVA DE LOS DELITOS DE RESISTENCIA O DESOBEDIENCIA A LA AUTORIDAD, CUANDO SE PRODUCE:', 'INGRESO INDEBIDO DE EQUIPOS O SISTEMA DE COMUNICACIÓN, FOTOGRAFÍA Y/O FILMACIÓN EN CENTROS DE DETENCIÓN O RECLUSIÓN.', 'ART. 368 - A', '184045'),
    (1922, 'SUB-1922', 'SBM4', '. ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE TORTURA SI LA VÍCTIMA:.', 'SE ENCUENTRA DETENIDA O RECLUIDA Y EL AGENTE ABUSA DE SU CONDICIÓN DE AUTORIDAD PARA COMETER EL DELITO.', 'ART. 321', '184046'),
    (1923, 'SUB-1923', 'SBM4', 'ES UNA MODALIDAD DELICTIVA DE LOS DELITOS DE RESISTENCIA O DESOBEDIENCIA A LA AUTORIDAD:', 'INGRESO INDEBIDO DE MATERIALES O COMPONENTES CON FINES DE ELABORACIÓN DE EQUIPOS DE COMUNICACIÓN EN CENTROS DE DETENCIÓN O RECLUSIÓN.', 'ART. 368 - B', '184047'),
    (1924, 'SUB-1924', 'SBM4', 'ES UNA MODALIDAD DELICTIVA DE LOS DELITOS DE RESISTENCIA Y DESOBEDIENCIA A LA AUTORIDAD:', 'SABOTAJE DE LOS EQUIPOS DE SEGURIDAD Y DE COMUNICACIÓN EN ESTABLECIMIENTOS PENITENCIARIOS.', 'ART. 368 - C', '184048'),
    (1925, 'SUB-1925', 'SBM4', 'EL MÉDICO O CUALQUIER PROFESIONAL SANITARIO QUE COOPERARA EN LA PERPETRACIÓN DEL DELITO DE TORTURA, SERÁ REPRIMIDO CON:.', 'LA MISMA PENA DE LOS AUTORES.', 'ART. 322', '184050'),
    (1926, 'SUB-1926', 'SBM4', 'ES UNA MODALIDAD DE LOS DELITOS DE DESOBEDIENCIA O RESISTENCIA A LA AUTORIDAD:', 'INGRESO INDEBIDO DE ARMAS, MUNICIONES O MATERIALES EXPLOSIVOS, INFLAMABLES, ASFIXIANTES O TÓXICOS EN ESTABLECIMIENTOS PENITENCIARIOS.', 'ART. 368 - E', '184051'),
    (1927, 'SUB-1927', 'SBM4', 'EL QUE, POR SÍ O MEDIANTE TERCEROS, REALIZA ACTOS DE DISTINCIÓN, EXCLUSIÓN, RESTRICCIÓN O PREFERENCIA QUE ANULAN O MENOSCABAN EL RECONOCIMIENTO, GOCE O EJERCICIO DE CUALQUIER DERECHO DE UNA PERSONA O GRUPO DE PERSONAS RECONOCIDO EN LA LEY, LA CONSTITUCIÓN O EN LOS TRATADOS DE DERECHOS HUMANOS DE LOS CUALES EL PERÚ ES PARTE, BASADOS EN MOTIVOS RACIALES, RELIGIOSOS, NACIONALIDAD, EDAD, SEXO, ORIENTACIÓN SEXUAL, IDENTIDAD DE GÉNERO, IDIOMA, IDENTIDAD ÉTNICA O CULTURAL, OPINIÓN, NIVEL SOCIO ECONÓMICO, CONDICIÓN MIGRATORIA, DISCAPACIDAD, CONDICIÓN DE SALUD, FACTOR GENÉTICO, FILIACIÓN, O CUALQUIER OTRO MOTIVO, COMETE DELITO DE:', 'DISCRIMINACIÓN E INCITACIÓN A LA DISCRIMINACIÓN.', 'ART. 323', '184052'),
    (1928, 'SUB-1928', 'SBM4', 'EL QUE, MEDIANTE VIOLENCIA O AMENAZA, IMPIDE A UNA AUTORIDAD ELEGIDA EN UN PROCESO ELECTORAL GENERAL, PARLAMENTARIO, REGIONAL O MUNICIPAL JURAMENTAR, ASUMIR O EJERCER SUS FUNCIONES, COMETE DELITO DE:.', 'VIOLENCIA CONTRA AUTORIDADES ELEGIDAS.', 'ART. 369', '184053'),
    (1929, 'SUB-1929', 'SBM4', 'EL QUE, POR SÍ, REALIZA ACTOS DE DISTINCIÓN, QUE ANULAN O MENOSCABAN EL RECONOCIMIENTO, GOCE O EJERCICIO DE CUALQUIER DERECHO DE UNA PERSONA O GRUPO DE PERSONAS RECONOCIDO EN LOS TRATADOS DE DERECHOS HUMANOS DE LOS CUALES EL PERÚ ES PARTE, BASADOS EN MOTIVOS DE ORIENTACIÓN SEXUAL, COMETE DELITO DE:.', 'DISCRIMINACIÓN E INCITACIÓN A LA DISCRIMINACIÓN.', 'ART. 323', '184055'),
    (1930, 'SUB-1930', 'SBM4', 'EL TESTIGO, PERITO, TRADUCTOR O INTÉRPRETE QUE, SIENDO LEGALMENTE REQUERIDO, SE ABSTIENE DE COMPARECER O PRESTAR LA DECLARACIÓN, INFORME O SERVICIO RESPECTIVO, COMETE DELITO DE:.', 'NEGATIVA A COLABORAR CON LA ADMINISTRACIÓN DE JUSTICIA.', 'ART. 371', '184056'),
    (1931, 'SUB-1931', 'SBM4', 'EL QUE SUSTRAE, OCULTA, CAMBIA, DESTRUYE O INUTILIZA OBJETOS, REGISTROS O DOCUMENTOS DESTINADOS A SERVIR DE PRUEBA ANTE LA AUTORIDAD COMPETENTE QUE SUSTANCIA UN PROCESO, CONFIADOS A LA CUSTODIA DE UN FUNCIONARIO O DE OTRA PERSONA, COMETE DELITO DE:.', 'ATENTADO CONTRA DOCUMENTOS QUE SIRVEN DE PRUEBA EN EL PROCESO.', 'ART. 372', '184057'),
    (1932, 'SUB-1932', 'SBM4', 'EL DELITO DE DISCRIMINACIÓN SE AGRAVA, SI EL HECHO SE REALIZA MEDIANTE ACTOS DE VIOLENCIA FISICA O MENTAL:', 'A TRAVÉS DEL INTERNET U OTRO MEDIO ANALOGO.', 'ART. 323', '184059'),
    (1933, 'SUB-1933', 'SBM4', 'EL QUE CAUSA DESORDEN EN LA SALA DE SESIONES DEL CONGRESO O DE LAS CÁMARAS LEGISLATIVAS, DE LAS ASAMBLEAS REGIONALES, DE LOS CONSEJOS MUNICIPALES O DE LOS TRIBUNALES DE JUSTICIA U OTRO LUGAR DONDE LAS AUTORIDADES PÚBLICAS EJERCEN SUS FUNCIONES O EL QUE ENTRA ARMADO EN DICHOS LUGARES; COMETE DELITO DE:.', 'PERTURBACIÓN DEL ORDEN EN EL LUGAR DONDE LA AUTORIDAD EJERCE SU FUNCIÓN.', 'ART. 375', '184060'),
    (1934, 'SUB-1934', 'SBM4', 'EL DELITO DE PELIGRO COMÚN, POR MEDIO DE INCENDIO, EXPLOSIÓN O LIBERANDO CUALQUIER CLASE DE ENERGÍA, CREA UN PELIGRO COMÚN PARA:', 'LAS PERSONAS O LOS BIENES.', 'ART. 273', '184062'),
    (1935, 'SUB-1935', 'SBM4', 'EL DELITO DE CONDUCCIÓN EN ESTADO DE EBRIEDAD O DROGADICCIÓN, CUANDO EL AGENTE PRESTA SERVICIO DE TRANSPORTE PÚBLICO DE PASAJEROS, SE CONFIGURA CUANDO HAY PRESENCIA DE ALCOHOL EN LA SANGRE EN PROPORCIÓN:.', 'SUPERIOR DE 0,25 GRAMOS-LITRO O BAJO EL EFECTO DE DROGAS TÓXICAS', 'ART. 274', '184063'),
    (1936, 'SUB-1936', 'SBM4', 'EL DELITO DE CONDUCCIÓN EN ESTADO DE EBRIEDAD O DROGADICCIÓN, SE CONFIGURA CUANDO HAY PRESENCIA DE ALCOHOL EN LA SANGRE EN PROPORCIÓN:.', 'MAYOR DE 0.5 GRAMOS-LITRO O BAJO EL EFECTO DE DROGAS TÓXICAS.', 'ART. 274', '184064'),
    (1937, 'SUB-1937', 'SBM4', 'EL DELITO DE MANIPULACIÓN EN ESTADO DE EBRIEDAD O DROGADICCIÓN, SE CONFIGURA CUANDO EL AGENTE OPERA O MANIOBRA HERRAMIENTA O MÁQUINA QUE REPRESENTE RIESGO O PELIGRO, CON PRESENCIA DE ALCOHOL EN LA SANGRE EN PROPORCIÓN:.', 'MAYOR DE 0.5 GRAMOS-LITRO, O BAJO EL EFECTO DE DROGAS TÓXICAS.', 'ART. 274 - A', '184065'),
    (1938, 'SUB-1938', 'SBM4', 'EL QUE ENCONTRÁNDOSE EN ESTADO DE EBRIEDAD, CON PRESENCIA DE ALCOHOL EN LA SANGRE EN PROPORCIÓN MAYOR DE 0.5 GRAMOS-LITRO, O BAJO EL EFECTO DE ESTUPEFACIENTES, DROGAS TÓXICAS, SUSTANCIAS PSICOTRÓPICAS O SINTÉTICAS, OPERA O MANIOBRA INSTRUMENTO, HERRAMIENTA, MÁQUINA U OTRO ANÁLOGO QUE REPRESENTE RIESGO O PELIGRO; COMETE:', 'DELITO DE PELIGRO COMÚN - MANIPULACIÓN DE INSTRUMENTOS EN ESTADO DE EBRIEDAD O DROGADICCIÓN.', 'ART. 274 - A', '184066'),
    (1939, 'SUB-1939', 'SBM4', 'EL QUE, PARA IMPEDIR O DIFICULTAR LAS TAREAS DE DEFENSA, SUSTRAE, OCULTA, DESTRUYE O INUTILIZA MATERIALES, INSTRUMENTOS U OTROS MEDIOS DESTINADOS A LA DEFENSA COMÚN, COMETE DELITO DE PELIGRO COMÚN EN LA MODALIDAD DE:.', 'DAÑOS DE OBRAS PARA LA DEFENSA COMÚN.', 'ART. 277', '184068'),
    (1940, 'SUB-1940', 'SBM4', 'QUE DELITO COMETE EL CONDUCTOR, CAPITÁN, COMANDANTE, PILOTO, TECNICO, MAQUINISTA O MECÁNICO DE CUALQUIER MEDIO DE TRANSPORTE, QUE ABANDONA SU RESPECTIVO SERVICIO ANTES DEL TÉRMINO DEL VIAJE:.', 'DELITO DE ABANDONO DE SERVICIO DE TRANSPORTE.', 'ART. 284', '184069'),
    (1941, 'SUB-1941', 'SBM4', 'EL QUE, SIN ESTAR DEBIDAMENTE AUTORIZADO, FABRICA, ENSAMBLA, MODIFICA, ALMACENA, SUMINISTRA, COMERCIALIZA, OFRECE O TIENE EN SU PODER BOMBAS, ARTEFACTOS O MATERIALES EXPLOSIVOS, INFLAMABLES, ASFIXIANTES O TÓXICOS O SUSTANCIAS O MATERIALES DESTINADOS PARA SU PREPARACIÓN; COMETE DELITO DE PELIGRO COMÚN EN LA MODALIDAD DE:.', 'FABRICACIÓN, SUMINISTRO O TENENCIA DE MATERIALES PELIGROSOS Y RESIDUOS PELIGROSOS.', 'ART. 279', '184071'),
    (1942, 'SUB-1942', 'SBM4', 'EL QUE, SIN ESTAR DEBIDAMENTE AUTORIZADO, TRANSFORMA O TRANSPORTA MATERIALES Y RESIDUOS PELIGROSOS SÓLIDOS, LÍQUIDOS, GASEOSOS U OTROS, QUE PONGA EN PELIGRO LA VIDA, SALUD, PATRIMONIO PÚBLICO O PRIVADO Y EL MEDIO AMBIENTE, COMETE DELITO DE PELIGRO COMÚN EN LA MODALIDAD DE:.', 'FABRICACIÓN, SUMINISTRO O TENENCIA DE MATERIALES PELIGROSOS Y RESIDUOS PELIGROSOS.', 'ART. 279', '184072'),
    (1943, 'SUB-1943', 'SBM4', 'EL QUE PRODUCE, DESARROLLA, COMERCIALIZA, ALMACENA, VENDE, ADQUIERE, USA O POSEE ARMAS QUÍMICAS, - CONTRAVINIENDO LAS PROHIBICIONES ESTABLECIDAS EN LA CONVENCIÓN SOBRE ARMAS QUÍMICAS ADOPTADA POR LAS NACIONES UNIDAS EN 1992- O LAS QUE TRANSFIERE A OTRO, O EL QUE PROMUEVE, FAVORECE O FACILITA QUE SE REALICEN DICHOS ACTOS, COMETE DELITO DE PELIGRO COMÚN EN LA MODALIDAD DE:.', 'PRODUCCIÓN, DESARROLLO Y COMERCIALIZACIÓN ILEGAL DE ARMAS QUÍMICAS.', 'ART. 279 - A', '184073'),
    (1944, 'SUB-1944', 'SBM4', 'EL QUE, SIN ESTAR DEBIDAMENTE AUTORIZADO, FABRICA, IMPORTA, EXPORTA, DEPOSITA, TRANSPORTA, COMERCIALIZA O USA PRODUCTOS PIROTÉCNICOS DE CUALQUIER TIPO, O LOS QUE VENDAN ESTOS PRODUCTOS A MENORES DE EDAD; COMETE DELITO DE:.', 'TRÁFICO DE PRODUCTOS PIROTÉCNICOS.', 'ART. 279 - C', '184075'),
    (1945, 'SUB-1945', 'SBM4', 'EL QUE, VALIÉNDOSE DE SU CONDICIÓN DE FUNCIONARIO O SERVIDOR PÚBLICO, CONDICIONA LA DISTRIBUCIÓN DE BIENES O LA PRESTACIÓN DE SERVICIOS CORRESPONDIENTES A PROGRAMAS PÚBLICOS DE APOYO O DESARROLLO SOCIAL, CON LA FINALIDAD DE OBTENER VENTAJA POLÍTICA Y/O ELECTORAL DE CUALQUIER TIPO EN FAVOR PROPIO O DE TERCEROS; COMETE:.', 'ABUSO DE AUTORIDAD CONDICIONANDO ILEGALMENTE LA ENTREGA DE BIENES Y SERVICIOS.', 'ART. 376 - A', '184077'),
    (1946, 'SUB-1946', 'SBM4', 'EL FUNCIONARIO PÚBLICO QUE, EN VIOLACIÓN DE SUS ATRIBUCIONES U OBLIGACIONES, OTORGA ILEGÍTIMAMENTE DERECHOS DE POSESIÓN O EMITE TÍTULOS DE PROPIEDAD SOBRE BIENES DE DOMINIO PÚBLICO O BIENES DE DOMINIO PRIVADO ESTATAL, O BIENES INMUEBLES DE PROPIEDAD PRIVADA, SIN CUMPLIR CON LOS REQUISITOS ESTABLECIDOS POR LA NORMATIVIDAD VIGENTE; COMETE DELITO DE:', 'OTORGAMIENTO ILEGÍTIMO DE DERECHOS SOBRE INMUEBLES.', 'ART. 376 - B', '184078'),
    (1947, 'SUB-1947', 'SBM4', 'EL POLICÍA QUE REHUSA, OMITE O RETARDA, SIN CAUSA JUSTIFICADA, LA PRESTACIÓN DE UN AUXILIO LEGALMENTE REQUERIDO POR LA AUTORIDAD CIVIL COMPETENTE; COMETE DELITO DE:.', 'DENEGACIÓN O DEFICIENTE APOYO POLICIAL.', 'ART. 378', '184080'),
    (1948, 'SUB-1948', 'SBM4', 'EL FUNCIONARIO PÚBLICO QUE REQUIERE LA ASISTENCIA DE LA FUERZA PÚBLICA PARA OPONERSE A LA EJECUCIÓN DE DISPOSICIONES U ÓRDENES LEGALES DE LA AUTORIDAD O CONTRA LA EJECUCIÓN DE SENTENCIA O MANDATO JUDICIAL, COMETE DELITO DE:.', 'REQUERIMIENTO INDEBIDO DE LA FUERZA PÚBLICA.', 'ART. 379', '184081'),
    (1949, 'SUB-1949', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PÚBLICO QUE, CON DAÑO DEL SERVICIO, ABANDONA SU CARGO SIN HABER CESADO LEGALMENTE EN EL DESEMPEÑO DEL MISMO, COMETE DELITO DE:.', 'ABANDONO DE CARGO.', 'ART. 380', '184082'),
    (1950, 'SUB-1950', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PÚBLICO QUE, ABUSANDO DE SU CARGO, OBLIGA O INDUCE A UNA PERSONA A DAR O PROMETER INDEBIDAMENTE, PARA SÍ O PARA OTRO, UN BIEN O UN BENEFICIO PATRIMONIAL, COMETE DELITO DE:.', 'CONCUSIÓN.', 'ART. 382', '184083'),
    (1951, 'SUB-1951', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PÚBLICO QUE, ABUSANDO DE SU CARGO, EXIGE O HACE PAGAR O ENTREGAR CONTRIBUCIONES O EMOLUMENTOS NO DEBIDOS O EN CANTIDAD QUE EXCEDE A LA TARIFA LEGAL, COMETE DELITO DE:.', 'COBRO INDEBIDO.', 'ART. 383', '184084'),
    (1952, 'SUB-1952', 'SBM4', 'EL QUE, VALIÉNDOSE DE SU CALIDAD DE FUNCIONARIO O SERVIDOR PÚBLICO, PATROCINA INTERESES DE PARTICULARES ANTE LA ADMINISTRACIÓN PÚBLICA, COMETE DELITO DE:.', 'PATROCINIO ILEGAL.', 'ART. 385', '184085'),
    (1953, 'SUB-1953', 'SBM4', 'COMETE DELITO DE PROMOCIÓN, FAVORECIMIENTO O FACILITAMIENTO DEL CONSUMO ILEGAL DE DROGAS TÓXICAS; EL QUE PROMUEVE, FAVORECE O FACILITA EL CONSUMO ILEGAL DE DROGAS TÓXICAS, SEAN ESTUPEFACIENTES, SUSTANCIAS PSICOTRÓPICAS O:', 'NUEVAS SUSTANCIAS PSICOACTIVAS', 'ART. 296', '184087'),
    (1954, 'SUB-1954', 'SBM4', 'EN EL DELITO DE PECULADO DOLOSO, SI LOS CAUDALES O EFECTOS ESTUVIERAN DESTINADOS A FINES ASISTENCIALES O A PROGRAMAS DE APOYO O INCLUSIÓN SOCIAL:', 'CONSTITUYE CIRCUNSTANCIA AGRAVANTE.', 'ART. 387', '184088'),
    (1955, 'SUB-1955', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PÚBLICO QUE, PARA FINES AJENOS AL SERVICIO, USA O PERMITE QUE OTRO USE VEHÍCULOS, MÁQUINAS O CUALQUIER OTRO INSTRUMENTO DE TRABAJO PERTENECIENTES A LA ADMINISTRACIÓN PÚBLICA O QUE SE HALLAN BAJO SU GUARDA, COMETE DELITO DE:.', 'PECULADO DE USO.', 'ART. 388', '184089'),
    (1956, 'SUB-1956', 'SBM4', 'EL DELITO DE PECULADO DE USO, ES APLICABLE AL CONTRATISTA DE UNA OBRA PÚBLICA O A SUS EMPLEADOS CUANDO LOS EFECTOS INDICADOS:.', 'PERTENECEN AL ESTADO O A CUALQUIER DEPENDENCIA PÚBLICA.', 'ART. 388', '184091'),
    (1957, 'SUB-1957', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PÚBLICO QUE DA AL DINERO O BIENES QUE ADMINISTRA UNA APLICACIÓN DEFINITIVA DIFERENTE DE AQUELLA A LOS QUE ESTÁN DESTINADOS, AFECTANDO EL SERVICIO O LA FUNCIÓN ENCOMENDADA, COMETE DELITO DE:.', 'MALVERSACIÓN.', 'ART. 389', '184092'),
    (1958, 'SUB-1958', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PÚBLICO QUE, REQUERIDO CON LAS FORMALIDADES DE LEY POR LA AUTORIDAD COMPETENTE, REHUSA ENTREGAR DINERO, COSAS O EFECTOS DEPOSITADOS O PUESTOS BAJO SU CUSTODIA O ADMINISTRACIÓN, COMETE:', 'REHUSAMIENTO A ENTREGA DE BIENES DEPOSITADOS O PUESTOS EN CUSTODIA.', 'ART. 391', '184094'),
    (1959, 'SUB-1959', 'SBM4', 'COMETE DELITO DE PROMOCIÓN, FAVORECIMIENTO O FACILITAMIENTO DEL CONSUMO ILEGAL DE DROGAS TÓXICAS; EL QUE FAVORECE EL CONSUMO ILEGAL DE DROGAS TÓXICAS, MEDIANTE ACTOS DE:', 'FABRICACIÓN O TRAFICO.', 'ART. 296', '184095'),
    (1960, 'SUB-1960', 'SBM4', 'ESTÁN SUJETOS A LOS DELITOS DE PECULADO DOLOSO Y CULPOSO, PECULADO DE USO Y MALVERSACIÓN, LOS:.', 'ADMINISTRADORES O DEPOSITARIOS DE DINERO O BIENES EMBARGADOS O DEPOSITADOS POR ORDEN DE AUTORIDAD COMPETENTE, AUNQUE PERTENEZCAN A PARTICULARES.', 'ART. 392', '184097'),
    (1961, 'SUB-1961', 'SBM4', '¿QUIÉNES ESTÁN SUJETOS A LOS DELITOS DE PECULADO DOLOSO Y CULPOSO, PECULADO DE USO Y MALVERSACIÓN?', 'LAS PERSONAS O REPRESENTANTES LEGALES DE PERSONAS JURÍDICAS QUE ADMINISTREN O CUSTODIEN DINERO O BIENES DESTINADOS A FINES ASISTENCIALES O A PROGRAMAS DE APOYO SOCIAL.', 'ART. 392', '184098'),
    (1962, 'SUB-1962', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PÚBLICO QUE ACEPTE O RECIBA DONATIVO, PROMESA O CUALQUIER OTRA VENTAJA O BENEFICIO, PARA REALIZAR U OMITIR UN ACTO EN VIOLACIÓN DE SUS OBLIGACIONES O EL QUE LAS ACEPTA A CONSECUENCIA DE HABER FALTADO A ELLAS, COMETE:.', 'COHECHO PASIVO PROPIO.', 'ART. 393', '184099'),
    (1963, 'SUB-1963', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PÚBLICO EXTRANJERO QUE ACEPTA, RECIBE O SOLICITA, DIRECTA O INDIRECTAMENTE, DONATIVO, PROMESA O CUALQUIER OTRA VENTAJA O BENEFICIO, PARA REALIZAR U OMITIR UN ACTO EN EL EJERCICIO DE SUS FUNCIONES OFICIALES, EN VIOLACIÓN DE SUS OBLIGACIONES, O LAS ACEPTA COMO CONSECUENCIA DE HABER FALTADO A ELLAS, PARA OBTENER O RETENER UN NEGOCIO U OTRA VENTAJA INDEBIDA, EN LA REALIZACIÓN DE ACTIVIDADES ECONÓMICAS INTERNACIONALES.', 'SOBORNO INTERNACIONAL PASIVO.', 'ART. 393 - A', '184100'),
    (1964, 'SUB-1964', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PÚBLICO QUE ACEPTE O RECIBA DONATIVO, PROMESA O CUALQUIER OTRA VENTAJA O BENEFICIO INDEBIDO PARA REALIZAR UN ACTO PROPIO DE SU CARGO O EMPLEO, SIN FALTAR A SU OBLIGACIÓN, O COMO CONSECUENCIA DEL YA REALIZADO, COMETE:.', 'COHECHO PASIVO IMPROPIO.', 'ART. 394', '184101'),
    (1965, 'SUB-1965', 'SBM4', 'EL MAGISTRADO, ÁRBITRO, FISCAL, PERITO, MIEMBRO DE TRIBUNAL ADMINISTRATIVO O CUALQUIER OTRO ANÁLOGO A LOS ANTERIORES QUE BAJO CUALQUIER MODALIDAD ACEPTE O RECIBA DONATIVO, PROMESA O CUALQUIER OTRA VENTAJA O BENEFICIO, A SABIENDAS QUE ES HECHO CON EL FIN DE INFLUIR O DECIDIR EN ASUNTO SOMETIDO A SU CONOCIMIENTO O COMPETENCIA, COMETE:', 'COHECHO PASIVO ESPECÍFICO.', 'ART. 395', '184103'),
    (1966, 'SUB-1966', 'SBM4', 'EL MAGISTRADO, ÁRBITRO, FISCAL, PERITO, MIEMBRO DE TRIBUNAL ADMINISTRATIVO O CUALQUIER OTRO ANÁLOGO A LOS ANTERIORES QUE BAJO CUALQUIER MODALIDAD SOLICITE, DIRECTA O INDIRECTAMENTE, DONATIVO, PROMESA O CUALQUIER OTRA VENTAJA O BENEFICIO, A SABIENDAS QUE ES HECHO CON EL FIN DE INFLUIR EN LA DECISIÓN DE UN ASUNTO QUE ESTÉ SOMETIDO A SU CONOCIMIENTO:.', 'COHECHO PASIVO ESPECIFICO.', 'ART. 395', '184104'),
    (1967, 'SUB-1967', 'SBM4', 'EL MIEMBRO DE LA POLICÍA NACIONAL QUE SOLICITA, DIRECTA O INDIRECTAMENTE, DONATIVO, PROMESA O CUALQUIER OTRA VENTAJA O BENEFICIO, PARA REALIZAR U OMITIR UN ACTO EN VIOLACIÓN DE SUS OBLIGACIONES DERIVADAS DE LA FUNCIÓN POLICIAL O A CONSECUENCIA DE HABER FALTADO A ELLAS, COMETE:.', 'COHECHO PASIVO PROPIO EN EL EJERCICIO DE LA FUNCIÓN POLICIAL.', 'ART. 395 - A', '184105'),
    (1968, 'SUB-1968', 'SBM4', 'SI EN EL CASO DEL DELITO DE COHECHO PASIVO ESPECÍFICO, EL AGENTE ES SECRETARIO JUDICIAL, RELATOR, ESPECIALISTA, AUXILIAR JURISDICCIONAL O CUALQUIER OTRO ANÁLOGO A LOS ANTERIORES, COMETE:.', 'CORRUPCIÓN PASIVA DE AUXILIARES JURISDICCIONALES.', 'ART. 396', '184107'),
    (1969, 'SUB-1969', 'SBM4', 'EL QUE, TENIENDO LA NACIONALIDAD PERUANA O LA REPRESENTACIÓN DE UNA PERSONA JURÍDICA DOMICILIADA EN EL PERÚ, BAJO CUALQUIER MODALIDAD, OFREZCA, OTORGUE O PROMETA DIRECTA O INDIRECTAMENTE A UN FUNCIONARIO O SERVIDOR PÚBLICO EXTRANJERO DONATIVO, PROMESA, VENTAJA O BENEFICIO INDEBIDO QUE REDUNDE EN SU PROPIO PROVECHO O EN EL DE OTRA PERSONA, PARA QUE DICHO SERVIDOR O FUNCIONARIO PÚBLICO REALICE U OMITA ACTOS PROPIOS DE SU CARGO O EMPLEO, EN VIOLACIÓN DE SUS OBLIGACIONES O SIN FALTAR A SU OBLIGACIÓN PARA OBTENER O RETENER UN NEGOCIO U OTRA VENTAJA INDEBIDA EN LA REALIZACIÓN DE ACTIVIDADES ECONÓMICAS O COMERCIALES INTERNACIONALES:', 'COHECHO ACTIVO TRANSNACIONAL.', 'ART. 397 - A', '184109'),
    (1970, 'SUB-1970', 'SBM4', 'EL QUE, BAJO CUALQUIER MODALIDAD, OFRECE, DA O PROMETE DONATIVO, VENTAJA O BENEFICIO A UN MAGISTRADO, FISCAL, PERITO, ÁRBITRO, MIEMBRO DE TRIBUNAL ADMINISTRATIVO O ANÁLOGO CON EL OBJETO DE INFLUIR EN LA DECISIÓN DE UN ASUNTO SOMETIDO A SU CONOCIMIENTO O COMPETENCIA:.', 'COHECHO ACTIVO ESPECÍFICO.', 'ART. 398', '184110'),
    (1971, 'SUB-1971', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PÚBLICO QUE INDEBIDAMENTE EN FORMA DIRECTA O INDIRECTA O POR ACTO SIMULADO SE INTERESA, EN PROVECHO PROPIO O DE TERCERO, POR CUALQUIER CONTRATO U OPERACIÓN EN QUE INTERVIENE POR RAZÓN DE SU CARGO:.', 'NEGOCIACIÓN INCOMPATIBLE O APROVECHAMIENTO INDEBIDO DEL CARGO.', 'ART. 399', '184112'),
    (1972, 'SUB-1972', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PÚBLICO QUE INDEBIDAMENTE EN FORMA DIRECTA O INDIRECTA O POR ACTO SIMULADO SE INTERESA, EN PROVECHO PROPIO O DE TERCERO, POR CUALQUIER CONTRATO U OPERACIÓN EN QUE INTERVIENE POR RAZÓN DE SU CARGO, COMETE:.', 'NEGOCIACION INCOMPATIBLE O APROVECHAMIENTO INDEBIDO DE CARGO', 'ART. 399', '184114'),
    (1973, 'SUB-1973', 'SBM4', 'CONSTITUYE UNA FORMA AGRAVADA DEL DELITO DE CONTAMINACIÓN DEL AMBIENTE:.', 'SI COMO EFECTO DE LA ACTIVIDAD CONTAMINANTE SE PRODUCEN LESIONES GRAVES O MUERTE.', 'ART. 305', '184115'),
    (1974, 'SUB-1974', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PÚBLICO QUE, ABUSANDO DE SU CARGO, INCREMENTA ILÍCITAMENTE SU PATRIMONIO RESPECTO DE SUS INGRESOS LEGÍTIMOS, COMETE:.', 'ENRIQUECIMIENTO ILÍCITO.', 'ART. 401', '184116'),
    (1975, 'SUB-1975', 'SBM4', 'ES UNA FORMA AGRAVADA DE CONTAMINACIÓN DEL AMBIENTE, EL QUE FALSEA U OCULTA INFORMACIÓN SOBRE EL HECHO CONTAMINANTE, LA CANTIDAD O CALIDAD DE LAS DESCARGAS, EMISIONES, FILTRACIONES, VERTIMIENTOS O RADIACIONES CONTAMINANTES REFERIDOS EN EL ARTÍCULO 304, A:', 'LA AUTORIDAD COMPETENTE O A LA INSTITUCIÓN AUTORIZADA PARA REALIZAR LABORES DE FISCALIZACIÓN O AUDITORÍA AMBIENTAL.', 'ART. 305', '184117'),
    (1976, 'SUB-1976', 'SBM4', 'EN EL DELITO DE ENRIQUECIMIENTO ILÍCITO, LOS BIENES DECOMISADOS E INCAUTADOS DURANTE LA INVESTIGACIÓN POLICIAL Y PROCESO JUDICIAL, SERÁN PUESTOS A DISPOSICIÓN DEL:.', 'MINISTERIO DE JUSTICIA.', 'ART. 401 - B', '184118'),
    (1977, 'SUB-1977', 'SBM4', 'EN EL DELITO DE ENRIQUECIMIENTO ILÍCITO, LOS BIENES DECOMISADOS O INCAUTADOS DEFINITIVAMENTE SERÁN ADJUDICADOS:.', 'AL ESTADO.', 'ART. 401 - B', '184119'),
    (1978, 'SUB-1978', 'SBM4', 'COMETE DELITO DE CONTAMINACION DEL AMBIENTE:.', 'EL QUE, INFRINGIENDO LEYES, REGLAMENTOS O LÍMITES MÁXIMOS PERMISIBLES, PROVOQUE O REALICE DESCARGAS, EMISIONES, EMISIONES DE GASES TÓXICOS, EMISIONES DE RUIDO, FILTRACIONES, VERTIMIENTOS O RADIACIONES CONTAMINANTES EN LA ATMÓSFERA, EL SUELO, EL SUBSUELO, LAS AGUAS TERRESTRES, MARÍTIMAS O SUBTERRÁNEAS, QUE CAUSE O PUEDA CAUSAR PERJUICIO, ALTERACIÓN O DAÑO GRAVE AL AMBIENTE O SUS COMPONENTES, LA CALIDAD AMBIENTAL O LA SALUD AMBIENTAL.', 'ART. 304', '184120'),
    (1979, 'SUB-1979', 'SBM4', 'EL QUE, SIN AUTORIZACIÓN O APROBACIÓN DE LA AUTORIDAD COMPETENTE, ESTABLECE UN VERTEDERO O BOTADERO DE RESIDUOS SÓLIDOS QUE PUEDA PERJUDICAR GRAVEMENTE LA CALIDAD DEL AMBIENTE, LA SALUD HUMANA, INCURRE EN:', 'INCUMPLIMIENTO DE LAS NORMAS RELATIVAS AL MANEJO DE RESIDUOS SÓLIDOS.', 'ART. 306', '184121'),
    (1980, 'SUB-1980', 'SBM4', 'EL QUE DENUNCIA A LA AUTORIDAD UN HECHO PUNIBLE, A SABIENDAS DE QUE NO SE HA COMETIDO O QUE HA SIDO COMETIDO POR PERSONA DISTINTA A LA DENUNCIADA, O EL QUE SIMULA O ADULTERA PRUEBAS O INDICIOS DE SU COMISIÓN QUE PUEDAN SERVIR DE MOTIVO PARA UN PROCESO PENAL O EL QUE FALSAMENTE SE ATRIBUYE DELITO NO COMETIDO O QUE HA SIDO COMETIDO POR OTRO:.', 'DENUNCIA CALUMNIOSA.', 'ART. 402', '184122'),
    (1981, 'SUB-1981', 'SBM4', 'EL QUE, CONTRAVINIENDO LEYES, REGLAMENTOS O DISPOSICIONES ESTABLECIDAS, UTILIZA DESECHOS SÓLIDOS PARA LA ALIMENTACIÓN DE ANIMALES DESTINADOS AL CONSUMO HUMANO ESTA INCURSO EN:.', 'INCUMPLIMIENTO DE LAS NORMAS RELATIVAS AL MANEJO DE RESIDUOS SÓLIDOS.', 'ART. 306', '184123'),
    (1982, 'SUB-1982', 'SBM4', 'EL QUE OCULTA A UN MENOR DE EDAD A LAS INVESTIGACIONES DE LA JUSTICIA O DE LA QUE REALIZA LA AUTORIDAD COMPETENTE, COMETE:.', 'OCULTAMIENTO DE MENOR A LAS INVESTIGACIONES.', 'ART. 403', '184124'),
    (1983, 'SUB-1983', 'SBM4', 'EL QUE INGRESE ILEGALMENTE AL TERRITORIO NACIONAL, SIN LA DEBIDA AUTORIZACIÓN, RESIDUOS O DESECHOS TÓXICOS O PELIGROSOS PARA EL AMBIENTE ESTA INCURSO EN:.', 'TRÁFICO ILEGAL DE RESIDUOS PELIGROSOS.', 'ART. 307', '184125'),
    (1984, 'SUB-1984', 'SBM4', 'EL QUE SUSTRAE A UNA PERSONA DE LA PERSECUCIÓN PENAL O A LA EJECUCIÓN DE UNA PENA O DE OTRA MEDIDA ORDENADA POR LA JUSTICIA, COMETE:.', 'ENCUBRIMIENTO PERSONAL.', 'ART. 404', '184126'),
    (1985, 'SUB-1985', 'SBM4', 'EL QUE TRASLADE O DISPONGA SIN LA DEBIDA AUTORIZACIÓN, RESIDUOS O DESECHOS TÓXICOS O PELIGROSOS PARA EL AMBIENTE, ESTA INCURSO EN:.', 'TRÁFICO ILEGAL DE RESIDUOS PELIGROSOS.', 'ART. 307', '184127'),
    (1986, 'SUB-1986', 'SBM4', 'EL QUE DIFICULTA LA ACCIÓN DE LA JUSTICIA PROCURANDO LA DESAPARICIÓN DE LAS HUELLAS O PRUEBA DEL DELITO U OCULTANDO LOS EFECTOS DEL MISMO, COMETE:.', 'ENCUBRIMIENTO REAL.', 'ART. 405', '184128'),
    (1987, 'SUB-1987', 'SBM4', 'EL QUE USE, EMPLEE, COLOQUE SIN LA DEBIDA AUTORIZACIÓN, RESIDUOS O DESECHOS TÓXICOS O PELIGROSOS PARA EL AMBIENTE ESTA INCURSO EN:.', 'TRÁFICO ILEGAL DE RESIDUOS PELIGROSOS.', 'ART. 307', '184129'),
    (1988, 'SUB-1988', 'SBM4', 'EL QUE HACE, EN TODO O EN PARTE, UN DOCUMENTO FALSO O ADULTERA UNO VERDADERO QUE PUEDA DAR ORIGEN A DERECHO U OBLIGACIÓN O SERVIR PARA PROBAR UN HECHO, CON EL PROPÓSITO DE UTILIZAR EL DOCUMENTO Y SI DE SU USO PUEDE RESULTAR ALGÚN PERJUICIO, COMETE DELITO DE:.', 'FALSIFICACIÓN DE DOCUMENTOS.', 'ART. 427', '184130'),
    (1989, 'SUB-1989', 'SBM4', 'EL QUE HACE USO DE UN DOCUMENTO FALSO O FALSIFICADO, COMO SI FUESE LEGÍTIMO, SIEMPRE QUE DE SU USO PUEDA RESULTAR ALGÚN PERJUICIO, COMETE:.', 'FALSIFICACIÓN DE DOCUMENTOS.', 'ART. 427', '184131'),
    (1990, 'SUB-1990', 'SBM4', 'EL QUE INSERTA O HACE INSERTAR, EN INSTRUMENTO PÚBLICO, DECLARACIONES FALSAS CONCERNIENTES A HECHOS QUE DEBAN PROBARSE CON EL DOCUMENTO, CON EL OBJETO DE EMPLEARLO COMO SI LA DECLARACIÓN FUERA CONFORME A LA VERDAD, COMETE DELITO DE:.', 'FALSEDAD IDEOLÓGICA.', 'ART. 428', '184132'),
    (1991, 'SUB-1991', 'SBM4', 'EL QUE, ESTANDO INCLUIDO DENTRO DEL RÉGIMEN DE LÍMITES MÁXIMOS DE CAPTURA POR EMBARCACIÓN ESTABLECIDO POR LEY, INSERTA O HACE INSERTAR EN CUALQUIER DOCUMENTO DONDE SE CONSIGNE LA INFORMACIÓN REFERENTE A LOS VOLÚMENES DE CAPTURA, INFORMACIÓN FALSA O DISTINTA RESPECTO AL VOLUMEN REALMENTE CAPTURADO, COMETE DELITO DE:.', 'FALSEDAD EN EL REPORTE DE LOS VOLÚMENES DE PESCA CAPTURADOS.', 'ART. 428 - B', '184133'),
    (1992, 'SUB-1992', 'SBM4', 'QUIEN ALTERA O AYUDA A LA ALTERACIÓN DE LOS INSTRUMENTOS DE PESAJE CON LOS QUE SE CALCULA LOS VOLÚMENES DE PESCA CAPTURADOS, SI DICHA ALTERACIÓN TIENE LA FINALIDAD DE CONSIGNAR UN VOLUMEN DISTINTO AL REALMENTE CAPTURADO, COMETE DELITO DE:.', 'FALSEDAD EN EL REPORTE DE LOS VOLÚMENES DE PESCA CAPTURADOS.', 'ART. 428 - B', '184134'),
    (1993, 'SUB-1993', 'SBM4', 'EL QUE OMITE EN UN DOCUMENTO PÚBLICO O PRIVADO DECLARACIONES QUE DEBERÍAN CONSTAR O EXPIDE DUPLICADOS CON IGUAL OMISIÓN, AL TIEMPO DE EJERCER UNA FUNCIÓN Y CON EL FIN DE DAR ORIGEN A UN HECHO U OBLIGACIÓN, COMETE DELITO DE:.', 'OMISIÓN DE CONSIGNAR DECLARACIONES EN DOCUMENTOS.', 'ART. 429', '184135'),
    (1994, 'SUB-1994', 'SBM4', 'EL QUE SUPRIME, DESTRUYE U OCULTA UN DOCUMENTO, EN TODO O EN PARTE DE MODO QUE PUEDA RESULTAR PERJUICIO PARA OTRO, CORRESPONDE A:.', 'SUPRESIÓN, DESTRUCCIÓN U OCULTAMIENTO DE DOCUMENTOS.', 'ART. 430', '184136'),
    (1995, 'SUB-1995', 'SBM4', 'EL MÉDICO QUE, MALICIOSAMENTE, EXPIDE UN CERTIFICADO FALSO RESPECTO A LA EXISTENCIA O NO EXISTENCIA, PRESENTE O PASADA, DE ENFERMEDADES FÍSICAS O MENTALES, COMETE DELITO DE:.', 'EXPEDICIÓN DE CERTIFICADO MÉDICO FALSO.', 'ART. 431', '184137'),
    (1996, 'SUB-1996', 'SBM4', 'SE COMETE DELITO DE EXPEDICIÓN DE CERTIFICADO MÉDICO FALSO, CUANDO SE HAYA DADO LA FALSA CERTIFICACIÓN CON EL OBJETO QUE SE ADMITA O INTERNE A UNA PERSONA EN UN HOSPITAL PARA:.', 'ENFERMOS MENTALES.', 'ART. 431', '184138'),
    (1997, 'SUB-1997', 'SBM4', 'TAMBIÉN COMETE DELITO DE EXPEDICIÓN DE CERTIFICADO MÉDICO FALSO:.', 'EL QUE HAGA USO MALICIOSO DE LA CERTIFICACIÓN.', 'ART. 431', '184139'),
    (1998, 'SUB-1998', 'SBM4', 'COMETE HURTO SIMPLE EL QUE PARA OBTENER PROVECHO:.', 'SE APODERA ILEGÍTIMAMENTE DE UN BIEN MUEBLE, TOTAL O PARCIALMENTE AJENO, SUSTRAYÉNDOLO DEL LUGAR DONDE SE ENCUENTRA.', 'ART. 185', '184140'),
    (1999, 'SUB-1999', 'SBM4', 'COMETE HURTO SIMPLE, EL QUE PARA OBTENER PROVECHO SE APODERA ILEGÍTIMAMENTE DE UN BIEN MUEBLE TOTAL O PARCIALMENTE AJENO, SUSTRAYÉNDOLO DEL LUGAR DONDE SE ENCUENTRA, EQUIPARÁNDOSE AL BIEN MUEBLE LO SIGUIENTE:', 'ENERGIA ELECTRICA.', 'ART. 185', '184141'),
    (2000, 'SUB-2000', 'SBM4', 'LOS TESTAMENTOS OLOGRAFO Y CERRADO, LOS TITULOS VALORES Y LOS TITULOS DE CREDITO TRASMISIBLES POR ENDOSO O AL PORTADOR CORRESPONDEN A:.', 'EQUIPARACION A DOCUMENTO PUBLICO.', 'ART. 433', '184142')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

