INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 2001 a 2100
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (2001, 'SUB-2001', 'SBM4', 'PARA EFECTOS DEL CAPÍTULO (FALSIFICACION DE DOCUMENTOS EN GENERAL)SE EQUIPARAN A DOCUMENTO PUBLICO:', 'LOS TESTAMENTOS OLÓGRAFOS Y CERRADOS', 'ART. 433', '184143'),
    (2002, 'SUB-2002', 'SBM4', 'PARA EFECTOS DEL CAPÍTULO DE FALSIFICACIÓN DE DOCUMENTOS EN GENERAL, SE EQUIPARAN A DOCUMENTO PÚBLICO:.', 'LOS TÍTULOS VALORES.', 'ART. 433', '184144'),
    (2003, 'SUB-2003', 'SBM4', 'PARA EFECTOS DEL CAPÍTULO DE FALSIFICACIÓN DE DOCUMENTOS EN GENERAL, SE EQUIPARAN A DOCUMENTO PÚBLICO:', 'LOS TÍTULOS DE CRÉDITO TRANSMISIBLES POR ENDOSO O AL PORTADOR.', 'ART. 433', '184145'),
    (2004, 'SUB-2004', 'SBM4', 'EN EL DELITO DE HURTO SIMPLE, SE EQUIPARA A BIEN MUEBLE:.', 'RECURSOS PESQUEROS OBJETO DE UN MECANISMO DE ASIGNACIÓN DE LÍMITES MÁXIMOS DE CAPTURA POR EMBARCACIÓN.', 'ART. 185', '184146'),
    (2005, 'SUB-2005', 'SBM4', 'CUANDO ALGUNOS DE LOS DELITOS PREVISTOS EN EL CAPÍTULO DE FALSIFICACIÓN DE DOCUMENTOS EN GENERAL, SEA COMETIDO POR UN FUNCIONARIO O SERVIDOR PÚBLICO O NOTARIO, CON ABUSO DE SUS FUNCIONES, SE LE IMPONDRÁ, ADEMÁS:.', 'LA PENA DE INHABILITACIÓN.', 'ART. 432', '184147'),
    (2006, 'SUB-2006', 'SBM4', 'LA AFECTACIÓN PSICOLÓGICA, COGNITIVA O CONDUCTUAL PUEDE SER DETERMINADA A TRAVÉS DE UN EXAMEN PERICIAL O CUALQUIER OTRO ELEMENTO PROBATORIO OBJETIVO SIMILAR AL QUE SEA EMITIDO POR ENTIDADES PÚBLICAS O PRIVADAS ESPECIALIZADAS EN LA MATERIA.', 'SIN SOMETERSE A LA EQUIVALENCIA DEL DAÑO PSÍQUICO.', 'ART. 124 - B', '184148'),
    (2007, 'SUB-2007', 'SBM4', '. EL QUE PARA OBTENER PROVECHO SE APODERA ILEGÍTIMAMENTE DE UN BIEN MUEBLE QUE FORMAN EL EQUIPAJE DE VIAJERO, SUSTRAYÉNDOLO DEL LUGAR DONDE SE ENCUENTRA, COMETE:.', 'HURTO AGRAVADO.', 'ART. 186', '184149'),
    (2008, 'SUB-2008', 'SBM4', 'COMETE DELITO CONTRA LA FE PÚBLICA, EL QUE, CON EL PROPÓSITO DE GOZAR DE LOS BENEFICIOS O COBERTURAS DEL SEGURO OBLIGATORIO DE ACCIDENTES DE TRÁNSITO, INCITA A:.', 'LA SIMULACIÓN O SIMULA LA OCURRENCIA DE ACCIDENTES DE TRÁNSITO.', 'ART. 431 - A', '184150'),
    (2009, 'SUB-2009', 'SBM4', 'EL QUE PARA OBTENER PROVECHO SE APODERA ILEGÍTIMAMENTE DE BIENES DE VALOR CIENTÍFICO, SUSTRAYÉNDOLOS DEL LUGAR DONDE SE ENCUENTRAN, COMETE DELITO DE:.', 'HURTO AGRAVADO.', 'ART. 186 Código Penal', '184151'),
    (2010, 'SUB-2010', 'SBM4', 'EL QUE FABRICA, FRAUDULENTAMENTE, O FALSIFICA SELLOS O TIMBRES OFICIALES DE VALOR, ESPECIALMENTE ESTAMPILLAS DE CORREOS, CON EL OBJETO DE EMPLEARLOS O HACER QUE LOS EMPLEEN OTRAS PERSONAS, O EL QUE DA A DICHOS SELLOS O TIMBRES OFICIALES YA USADOS LA APARIENCIA DE VALIDEZ PARA EMPLEARLOS NUEVAMENTE; COMETE DELITO DE:.', 'FABRICACIÓN O FALSIFICACIÓN DE SELLOS O TIMBRES OFICIALES.', 'ART. 434', '184152'),
    (2011, 'SUB-2011', 'SBM4', 'EL QUE, PARA OBTENER PROVECHO SE APODERA ILEGÍTIMAMENTE DE BIENES QUE INTEGREN EL PATRIMONIO CULTURAL DE LA NACIÓN, SUSTRAYÉNDOLOS DEL LUGAR DONDE SE ENCUENTRA. COMETE DELITO DE:.', 'HURTO AGRAVADO.', 'ART. 186', '184153'),
    (2012, 'SUB-2012', 'SBM4', 'EL QUE PARA OBTENER PROVECHO SE APODERA ILEGÍTIMAMENTE DE BIENES MUEBLES MEDIANTE DESTREZA, ESCALAMIENTO, DESTRUCCIÓN O ROTURA DE OBSTÁCULOS, SUSTRAYÉNDOLO DEL LUGAR DONDE SE ENCUENTRA. COMETE:', 'HURTO AGRAVADO.', 'ART. 186', '184154'),
    (2013, 'SUB-2013', 'SBM4', 'COMETE DELITO DE FABRICACIÓN O FALSIFICACIÓN DE SELLOS O TIMBRES OFICIALES, CUANDO EL AGENTE EMPLEA COMO AUTÉNTICOS O TODAVÍA VÁLIDOS; LOS:', 'SELLOS O TIMBRES OFICIALES DE VALOR QUE SON FALSOS, FALSIFICADOS O YA USADOS.', 'ART. 434', '184155'),
    (2014, 'SUB-2014', 'SBM4', 'EL QUE FABRICA, FRAUDULENTAMENTE, O FALSIFICA MARCAS O CONTRASEÑAS OFICIALES DESTINADAS A HACER CONSTAR EL RESULTADO DE UN EXAMEN DE LA AUTORIDAD O LA CONCESIÓN DE UN PERMISO O LA IDENTIDAD DE UN OBJETO O EL QUE A SABIENDAS DE SU PROCEDENCIA ILÍCITA HACE USO DE TALES MARCAS; COMETE DELITO DE:.', 'FABRICACIÓN FRAUDULENTA O FALSIFICACIÓN DE MARCAS O CONTRASEÑAS OFICIALES.', 'ART. 435', '184156'),
    (2015, 'SUB-2015', 'SBM4', 'EL QUE VENDE LA PRENDA CONSTITUIDA EN SU FAVOR O SE APROPIA O DISPONE DE ELLA SIN OBSERVAR LAS FORMALIDADES LEGALES, COMETE DELITO DE:. Código Penal', 'APROPIACIÓN DE PRENDA.', 'ART. 193', '184157'),
    (2016, 'SUB-2016', 'SBM4', 'CUANDO EL AGENTE DE ALGUNO DE LOS DELITOS DE FALSIFICACIÓN DE SELLOS,TIMBRES Y MARCAS OFICIALES ES FUNCIONARIO O SERVIDOR PÚBLICO, SERÁ REPRIMIDO, ADEMÁS, CON PENA DE:', 'INHABILITACIÓN.', 'ART. 436', '184158'),
    (2017, 'SUB-2017', 'SBM4', 'EL QUE PARA OBTENER PROVECHO SE APODERA ILEGÍTIMAMENTE DE UN BIEN MUEBLE, TOTAL O PARCIALMENTE AJENO, CON EL CONCURSO DE DOS O MÁS PERSONAS, SUSTRAYÉNDOLO DEL LUGAR DONDE SE ENCUENTRA, COMETE EL DELITO DE:.', 'HURTO AGRAVADO.', 'ART. 186', '184159'),
    (2018, 'SUB-2018', 'SBM4', 'EL QUE, TENIENDO TÍTULO, ANUNCIA O PROMETE LA CURACIÓN DE ENFERMEDADES A TÉRMINO FIJO O POR MEDIOS SECRETOS O INFALIBLES, COMETE DELITO DE:.', 'EJERCICIO MALICIOSO Y DESLEAL DE LA MEDICINA.', 'ART. 291', '184160'),
    (2019, 'SUB-2019', 'SBM4', 'LAS DISPOSICIONES CONSIGNADAS EN EL CAPÍTULO DE FABRICACIÓN O FALSIFICACIÓN DE SELLOS O TIMBRES OFICIALES SON APLICABLES A LOS SELLOS, MARCAS OFICIALES Y TIMBRES DE:.', 'PROCEDENCIA EXTRANJERA.', 'ART. 437', '184161'),
    (2020, 'SUB-2020', 'SBM4', 'EL QUE, POR CUALQUIER MEDIO FRAUDULENTO, INDUCE A ERROR A UN FUNCIONARIO O SERVIDOR PÚBLICO PARA OBTENER RESOLUCIÓN CONTRARÍA A LA LEY, COMETE:.', 'FRAUDE PROCESAL.', 'ART. 416', '184162'),
    (2021, 'SUB-2021', 'SBM4', 'EL QUE PARA OBTENER PROVECHO SE APODERA ILEGÍTIMAMENTE DE UN BIEN MUEBLE, TOTAL O PARCIALMENTE AJENO, COMO VEHÍCULO AUTOMOTOR, SUSTRAYÉNDOLO DEL LUGAR DONDE SE ENCUENTRA. COMETE:.', 'HURTO AGRAVADO.', 'ART. 186', '184163'),
    (2022, 'SUB-2022', 'SBM4', 'EL QUE OTORGUE, EXPIDA U OFERTE CERTIFICADOS, DIPLOMAS U OTRAS CONSTANCIAS QUE ATRIBUYAN GRADO ACADÉMICO, TÍTULO PROFESIONAL, TÍTULO DE SEGUNDA ESPECIALIDAD PROFESIONAL, NIVEL DE ESPECIALIZACIÓN U OTRA CAPACIDAD ANÁLOGA, SIN QUE EL BENEFICIARIO HAYA LLEVADO EFECTIVAMENTE LOS ESTUDIOS CORRESPONDIENTES; COMETE DELITO DE:.', 'FALSEDAD GENÉRICA AGRAVADA.', 'ART. 438 - A', '184164'),
    (2023, 'SUB-2023', 'SBM4', 'EL QUE PARA OBTENER PROVECHO SE APODERA ILEGÍTIMAMENTE DE UN BIEN MUEBLE, TOTAL O PARCIALMENTE AJENO, QUE CONSTITUYA ÚNICO MEDIO DE SUBSISTENCIA DE LA VÍCTIMA, SUSTRAYÉNDOLO DEL LUGAR DONDE SE ENCUENTRA. COMETE:.', 'HURTO AGRAVADO.', 'ART. 186', '184165'),
    (2024, 'SUB-2024', 'SBM4', 'EL QUE DE CUALQUIER OTRO MODO QUE NO ESTÉ ESPECIFICADO EN LOS CAPÍTULOS CORRESPONDIENTES AL DELITO CONTRA LA FE PUBLICA, COMETE FALSEDAD SIMULANDO, SUPONIENDO, ALTERANDO LA VERDAD INTENCIONALMENTE Y CON PERJUICIO DE TERCEROS, POR PALABRAS, HECHOS O USURPANDO NOMBRE, CALIDAD O EMPLEO QUE NO LE CORRESPONDE, SUPONIENDO VIVA A UNA PERSONA FALLECIDA O QUE NO HA EXISTIDO O VICEVERSA; COMETE:.', 'FALSEDAD GENÉRICA.', 'ART. 438', '184166'),
    (2025, 'SUB-2025', 'SBM4', 'EL QUE PARA OBTENER PROVECHO SE APODERA ILEGÍTIMAMENTE DE UN BIEN MUEBLE, TOTAL O PARCIALMENTE AJENO, EMPLEANDO MATERIALES O ARTEFACTOS EXPLOSIVOS PARA LA DESTRUCCIÓN O ROTURA DE OBSTÁCULOS, SUSTRAYÉNDOLO DEL LUGAR DONDE SE ENCUENTRA. COMETE:.', 'HURTO AGRAVADO.', 'ART. 186', '184167'),
    (2026, 'SUB-2026', 'SBM4', 'EL QUE, A SABIENDAS, FABRICA O INTRODUCE EN EL TERRITORIO DE LA REPÚBLICA O CONSERVA EN SU PODER MÁQUINAS, CUÑOS, MARCAS O CUALQUIER OTRA CLASE DE ÚTILES O INSTRUMENTOS, DESTINADOS A LA FALSIFICACIÓN DE TIMBRES, ESTAMPILLAS, MARCAS OFICIALES O CUALQUIER ESPECIE VALORADA; COMETE:.', 'FABRICACIÓN O TENENCIA DE INSTRUMENTOS PARA FALSIFICAR.', 'ART. 439', '184168'),
    (2027, 'SUB-2027', 'SBM4', 'EL QUE PARA OBTENER PROVECHO SE APODERA ILEGÍTIMAMENTE DE UN BIEN MUEBLE, TOTAL O PARCIALMENTE AJENO, DURANTE LA NOCHE, SUSTRAYÉNDOLO DEL LUGAR DONDE SE ENCUENTRA. COMETE:.', 'HURTO AGRAVADO.', 'ART. 186', '184169'),
    (2028, 'SUB-2028', 'SBM4', 'EL QUE SUSTRAE UN BIEN MUEBLE AJENO, CON EL FIN DE HACER USO MOMENTÁNEO Y LO DEVUELVE; COMETE DELITO DE:.', 'HURTO DE USO.', 'ART. 187', '184170'),
    (2029, 'SUB-2029', 'SBM4', 'EL JUEZ QUE SE NIEGA A ADMINISTRAR JUSTICIA O QUE ELUDE JUZGAR BAJO PRETEXTO DE DEFECTO O DEFICIENCIA DE LA LEY, INCURRE EN:.', 'NEGATIVA A ADMINISTRAR JUSTICIA', 'ART. 422', '184171'),
    (2030, 'SUB-2030', 'SBM4', 'EL QUE SE APODERA ILEGÍTIMAMENTE DE UN BIEN MUEBLE TOTALMENTE O PARCIALMENTE AJENO, PARA APROVECHARSE DE ÉL, SUSTRAYÉNDOLO DEL LUGAR EN QUE SE ENCUENTRA, EMPLEANDO VIOLENCIA CONTRA LA PERSONA; COMETE:', 'ROBO.', 'ART. 188', '184172'),
    (2031, 'SUB-2031', 'SBM4', 'EL QUE REALICE ACTIVIDAD DE EXPLORACIÓN, EXTRACCIÓN, EXPLOTACIÓN U OTRO ACTO SIMILAR DE RECURSOS MINERALES METÁLICOS Y NO METÁLICOS SIN CONTAR CON LA AUTORIZACIÓN DE LA ENTIDAD ADMINISTRATIVA COMPETENTE QUE CAUSE O PUEDA CAUSAR PERJUICIO, ALTERACIÓN O DAÑO AL AMBIENTE Y SUS COMPONENTES, LA CALIDAD AMBIENTAL O LA SALUD AMBIENTAL COMETE DELITO:.', 'DE MINERÍA ILEGAL.', 'ART. 307 - A', '184173'),
    (2032, 'SUB-2032', 'SBM4', 'EL QUE SE APODERA ILEGÍTIMAMENTE DE UN VEHÍCULO AUTOMOTOR PARCIALMENTE AJENO, PARA APROVECHARSE DE ÉL, SUSTRAYÉNDOLO DEL LUGAR EN QUE SE ENCUENTRA, EMPLEANDO VIOLENCIA CONTRA LA PERSONA, COMETE:.', 'ROBO AGRAVADO.', 'ART. 189', '184174'),
    (2033, 'SUB-2033', 'SBM4', 'EL QUE, SE APODERA ILEGÍTIMAMENTE DE AUTOPARTES O ACCESORIOS DE VEHÍCULO AUTOMOTOR, TOTAL O PARCIALMENTE AJENOS, PARA APROVECHARSE DE ELLOS, SUSTRAYÉNDOLOS DEL LUGAR EN QUE SE ENCUENTRAN, EMPLEANDO VIOLENCIA CONTRA LA PERSONA, COMETE:.', 'ROBO AGRAVADO.', 'ART. 189', '184175'),
    (2034, 'SUB-2034', 'SBM4', 'EL QUE SE APODERA ILEGÍTIMAMENTE DE UN BIEN MUEBLE PARCIALMENTE AJENO, PARA APROVECHARSE DE ÉL, SUSTRAYÉNDOLO DEL LUGAR EN QUE SE ENCUENTRA, EMPLEANDO VIOLENCIA Y EN AGRAVIO DE UN MENOR, COMETE DELITO DE:.', 'ROBO AGRAVADO.', 'ART. 189', '184176'),
    (2035, 'SUB-2035', 'SBM4', 'ES UNA FORMA AGRAVADA DE MINERÍA ILEGAL, LA QUE SE REALIZA EN :.', 'ZONAS NO PERMITIDAS PARA EL DESARROLLO DE ACTIVIDAD MINERA.', 'ART. 307 - B', '184177'),
    (2036, 'SUB-2036', 'SBM4', 'EL QUE SE APODERA ILEGÍTIMAMENTE DE BIENES DE VALOR CIENTÍFICO, PARA APROVECHARSE DE ELLOS, SUSTRAYÉNDOLES DEL LUGAR EN QUE SE ENCUENTRAN, EMPLEANDO VIOLENCIA CONTRA LA PERSONA, COMETE DELITO DE:.', 'ROBO AGRAVADO.', 'ART. 189 Código Penal', '184178'),
    (2037, 'SUB-2037', 'SBM4', 'CUÁL DE LOS SUPUESTOS, ES UNA FORMA AGRAVADA DE MINERÍA ILEGAL:', 'EN ÁREAS NATURALES PROTEGIDAS.', 'ART. 307 - B', '184179'),
    (2038, 'SUB-2038', 'SBM4', 'CUANDO EL HECHO RECAE SOBRE BIENES QUE INTEGREN EL PATRIMONIO CULTURAL DE LA NACIÓN, PARA APROVECHARSE DE ELLOS, SUSTRAYÉNDOLOS DEL LUGAR EN QUE SE ENCUENTRAN, EMPLEANDO VIOLENCIA CONTRA LA PERSONA, COMETE DELITO DE:.', 'ROBO AGRAVADO.', 'ART. 189', '184180'),
    (2039, 'SUB-2039', 'SBM4', 'EL QUE MEDIANTE VIOLENCIA O AMENAZA OBLIGA A UNA PERSONA O A UNA INSTITUCIÓN PÚBLICA O PRIVADA A OTORGAR AL AGENTE O A UN TERCERO UNA VENTAJA ECONÓMICA INDEBIDA U OTRA VENTAJA DE CUALQUIER OTRA ÍNDOLE; COMETE:.', 'EXTORSIÓN.', 'ART. 200', '184181'),
    (2040, 'SUB-2040', 'SBM4', 'CUAL DE LOS SUPUESTOS ES UNA FORMA AGRAVADA DE MINERÍA ILEGAL:.', 'UTILIZANDO DRAGAS, ARTEFACTOS U OTROS INSTRUMENTOS SIMILARES.', 'ART. 307 - B', '184182'),
    (2041, 'SUB-2041', 'SBM4', 'EL QUE, HACIENDO SABER A OTRO QUE SE DISPONE A PUBLICAR, UN HECHO O CONDUCTA CUYA DIVULGACIÓN PUEDE PERJUDICARLO PERSONALMENTE, TRATA DE DETERMINARLO O LO DETERMINA A COMPRAR SU SILENCIO; COMETE:.', 'CHANTAJE.', 'ART. 201', '184183'),
    (2042, 'SUB-2042', 'SBM4', 'CUAL DE LOS SUPUESTOS ES UNA FORMA AGRAVADA DE MINERÍA ILEGAL :.', 'SI EL AGENTE EMPLEA INSTRUMENTOS U OBJETOS CAPACES DE PONER EN PELIGRO LA VIDA, LA SALUD O EL PATRIMONIO DE LAS PERSONAS.', 'ART. 307 - B', '184184'),
    (2043, 'SUB-2043', 'SBM4', 'EL QUE PROCURA PARA SÍ O PARA OTRO UN PROVECHO ILÍCITO EN PERJUICIO DE TERCERO, INDUCIENDO O MANTENIENDO EN ERROR AL AGRAVIADO MEDIANTE ENGAÑO, ASTUCIA, ARDID U OTRA FORMA FRAUDULENTA; COMETE DELITO DE:.', 'ESTAFA.', 'ART. 196', '184185'),
    (2044, 'SUB-2044', 'SBM4', 'ES UNA FORMA AGRAVADA DE MINERÍA ILEGAL, CUANDO:.', 'SE AFECTA SISTEMAS DE IRRIGACIÓN O AGUAS DESTINADOS AL CONSUMO HUMANO.', 'ART. 307 - B', '184186'),
    (2045, 'SUB-2045', 'SBM4', 'EL QUE, CON VIOLENCIA, AMENAZA, ENGAÑO O ABUSO DE CONFIANZA, DESPOJA A OTRO, TOTAL O PARCIALMENTE, DE LA POSESIÓN O TENENCIA DE UN INMUEBLE O DEL EJERCICIO DE UN DERECHO REAL, COMETE DELITO DE:.', 'USURPACIÓN.', 'ART. 202', '184187'),
    (2046, 'SUB-2046', 'SBM4', 'ES UNA FORMA AGRAVADA DE MINERÍA ILEGAL, CUANDO:.', 'EL AGENTE EMPLEA PARA LA COMISIÓN DEL DELITO A MENORES DE EDAD U OTRA PERSONA INIMPUTABLE.', 'ART. 307 - B', '184188'),
    (2047, 'SUB-2047', 'SBM4', 'ES UNA FORMA DE USURPACIÓN AGRAVADA, CUANDO LA USURPACIÓN SE COMETE:.', 'SOBRE BIENES DESTINADOS A SERVICIOS PÚBLICOS.', 'ART. 204', '184189'),
    (2048, 'SUB-2048', 'SBM4', 'EL QUE OBSTACULIZA O IMPIDE LA ACTIVIDAD DE EVALUACIÓN, CONTROL Y FISCALIZACIÓN DE LA AUTORIDAD ADMINISTRATIVA RELACIONADA CON LA MINERÍA ILEGAL; COMETE DELITO DE :.', 'OBSTACULIZACIÓN DE LA FISCALIZACIÓN ADMINISTRATIVA.', 'ART. 307 - D', '184190'),
    (2049, 'SUB-2049', 'SBM4', 'EL QUE MUTILA UN MIEMBRO U ÓRGANO PRINCIPAL DEL CUERPO O LO HACEN IMPROPIO PARA SU FUNCIÓN, COMETE:.', 'LESIONES GRAVES.', 'ART. 121', '184191'),
    (2050, 'SUB-2050', 'SBM4', '. EL QUE, INFRINGIENDO LAS LEYES Y REGLAMENTOS, ADQUIERE, VENDE, DISTRIBUYE, COMERCIALIZA, TRANSPORTA, IMPORTA, POSEE O ALMACENA INSUMOS QUÍMICOS, CON EL PROPÓSITO DE DESTINAR DICHOS BIENES A LA COMISIÓN DE LOS DELITOS DE MINERÍA ILEGAL; COMETE DELITO DE:.', 'TRÁFICO ILÍCITO DE INSUMOS QUÍMICOS Y MAQUINARIAS DESTINADOS A MINERÍA ILEGAL', 'ART. 307 - E', '184192'),
    (2051, 'SUB-2051', 'SBM4', 'EL QUE ADQUIERE, VENDE, ARRIENDA, TRANSFIERE O CEDE EN USO BAJO CUALQUIER TÍTULO, DISTRIBUYE, COMERCIALIZA, TRANSPORTA, IMPORTA, POSEE O ALMACENA MAQUINARIAS, A SABIENDAS DE QUE SERÁN DESTINADAS A LA COMISIÓN DE LOS DELITOS DE MINERÍA ILEGAL; COMETE DELITO DE:.', 'TRÁFICO ILÍCITO DE INSUMOS QUÍMICOS Y MAQUINARIAS DESTINADOS A MINERÍA ILEGAL.', 'ART. 307 - E', '184193'),
    (2052, 'SUB-2052', 'SBM4', 'EL AGENTE DE LOS DELITOS DE MINERÍA ILEGAL SERÁ ADEMÁS SANCIONADO, DE CONFORMIDAD CON EL ARTÍCULO 36, INCISO 4,CON LA PENA DE:.', 'INHABILITACIÓN PARA OBTENER, A NOMBRE PROPIO O A TRAVÉS DE TERCEROS, CONCESIONES MINERAS POR UN PERIODO IGUAL AL DE LA PENA PRINCIPAL.', 'ART. 307 - F', '184194'),
    (2053, 'SUB-2053', 'SBM4', 'EL QUE, MEDIANTE VIOLENCIA O AMENAZA, TOMA LOCALES, OBSTACULIZA VÍAS DE COMUNICACIÓN O IMPIDE EL LIBRE TRÁNSITO DE LA CIUDADANÍA O PERTURBA EL NORMAL FUNCIONAMIENTO DE LOS SERVICIOS PÚBLICOS O LA EJECUCIÓN DE OBRAS LEGALMENTE AUTORIZADAS, CON EL OBJETO DE OBTENER DE LAS AUTORIDADES CUALQUIER BENEFICIO O VENTAJA ECONÓMICA INDEBIDA, INCURRE EN DELITO DE:', 'EXTORSIÓN.', 'ART. 200', '184195'),
    (2054, 'SUB-2054', 'SBM4', 'CUAL DE LOS SIGUIENTES ENUNCIADOS, ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE RUFIANISMO:.', 'LA VICTIMA ES CONYUGUE.', 'ART. 180', '184196'),
    (2055, 'SUB-2055', 'SBM4', '¿CUÁL DE LOS SIGUIENTES ENUNCIADOS; ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE PROXENETISMO?:', 'LA VICTIMA ESTE EN SITUACION DE ABANDONO.', 'ART. 181', '184197'),
    (2056, 'SUB-2056', 'SBM4', 'EL QUE, EN SU PROVECHO O DE UN TERCERO, SE APROPIA INDEBIDAMENTE DE UN BIEN MUEBLE, UNA SUMA DE DINERO O UN VALOR QUE HA RECIBIDO EN COMISIÓN, QUE PRODUZCA OBLIGACIÓN DE ENTREGAR, DEVOLVER, O HACER UN USO DETERMINADO, COMETE DELITO DE:.', 'APROPIACIÓN ILÍCITA.', 'ART. 190', '184198'),
    (2057, 'SUB-2057', 'SBM4', 'EL CURADOR, TUTOR O ALBACEA, QUE EN SU PROVECHO SE APROPIA INDEBIDAMENTE DE UN BIEN MUEBLE QUE HA RECIBIDO EN COMISIÓN, QUE PRODUZCA OBLIGACIÓN DE DEVOLVER, COMETE DELITO DE:.', 'APROPIACIÓN ILÍCITA COMÚN.', 'ART. 190', '184199'),
    (2058, 'SUB-2058', 'SBM4', 'SEGÚN EL BIEN OBJETO DEL HECHO, ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE APROPIACIÓN ILÍCITA:.', 'BIENES DESTINADOS AL AUXILIO DE POBLACIONES QUE SUFREN LAS CONSECUENCIAS DE DESASTRES NATURALES.', 'ART. 190', '184200'),
    (2059, 'SUB-2059', 'SBM4', 'EL PROPIETARIO DE UN BIEN MUEBLE QUE LO SUSTRAE DE QUIEN LO TENGA LEGÍTIMAMENTE EN SU PODER, CON PERJUICIO DE ÉSTE O DE UN TERCERO COMETE EL DELITO DE:. Código Penal', 'SUSTRACCIÓN DE BIEN PROPIO.', 'ART. 191', '184201'),
    (2060, 'SUB-2060', 'SBM4', 'EL QUE ADQUIERE, RECIBE EN DONACIÓN O EN PRENDA O GUARDA, ESCONDE, VENDE O AYUDA A NEGOCIAR UN BIEN DE CUYA PROCEDENCIA DELICTUOSA TENÍA CONOCIMIENTO O DEBÍA PRESUMIR QUE PROVENÍA DE UN DELITO, COMETE EL DELITO DE:.', 'RECEPTACIÓN.', 'ART. 194', '184202'),
    (2061, 'SUB-2061', 'SBM4', 'CUÁL DE LOS SIGUIENTES ENUNCIADOS PRESENTADOS, ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE RECEPTACIÓN:', 'EL BIEN ES PROPIEDAD DEL ESTADO DESTINADO AL USO PÚBLICO.', 'ART. 195', '184203'),
    (2062, 'SUB-2062', 'SBM4', 'EL JUEZ O EL FISCAL QUE DICTA RESOLUCIÓN O EMITE DICTAMEN, MANIFIESTAMENTE CONTRARIOS AL TEXTO EXPRESO Y CLARO DE LA LEY, O CITA PRUEBAS INEXISTENTES O HECHOS FALSOS, O SE APOYA EN LEYES SUPUESTAS O DEROGADAS. COMETE EL DELITO DE:', 'PREVARICATO.', 'ART. 418', '184204'),
    (2063, 'SUB-2063', 'SBM4', 'CUAL DE LOS SIGUIENTES ENUNCIADOS, ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE RECEPTACIÓN:.', 'EL BIEN ES PROPIEDAD DEL ESTADO DESTINADO A PROGRAMAS DE APOYO SOCIAL.', 'ART. 195', '184205'),
    (2064, 'SUB-2064', 'SBM4', 'CUAL DE LOS SIGUIENTES ENUNCIADOS, ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE RECEPTACION:.', 'EL BIEN ES VEHÍCULO AUTOMOTOR, SUS AUTOPARTES O ACCESORIOS.', 'ART. 195', '184206'),
    (2065, 'SUB-2065', 'SBM4', '¿CUÁL DE LOS SIGUIENTES ENUNCIADOS, ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE RECEPTACIÓN?:', 'EL BIEN ES GAS, HIDROCARBUROS O PRODUCTOS DERIVADOS.', 'ART. 195', '184207'),
    (2066, 'SUB-2066', 'SBM4', '¿CUÁL DE LOS SIGUIENTES ENUNCIADOS, NO ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE RECEPTACIÓN?:', 'EL BIEN ES MEDICINA E INSTRUMENTAL MEDICO.', 'ART. 195', '184208'),
    (2067, 'SUB-2067', 'SBM4', 'LA EXTORSIÓN AGRAVADA, ES UNA MODALIDAD DEL DELITO:', 'CONTRA EL PATRIMONIO.', 'ART. 200', '184209'),
    (2068, 'SUB-2068', 'SBM4', 'EL FUNCIONARIO PÚBLICO CON PODER DE DECISIÓN QUE, CONTRAVINIENDO LO ESTABLECIDO EN EL ART. 42° DE LA CONSTITUCIÓN POLÍTICA DEL PERÚ, PARTICIPE EN UNA HUELGA CON EL OBJETO DE OBTENER PARA SÍ O PARA TERCEROS CUALQUIER BENEFICIO O VENTAJA ECONÓMICA INDEBIDA U OTRA VENTAJA DE CUALQUIER OTRA ÍNDOLE COMETE EL DELITO:.', 'CONTRA EL PATRIMONIO – EXTORSIÓN.', 'ART. 200', '184210'),
    (2069, 'SUB-2069', 'SBM4', 'EL QUE MEDIANTE VIOLENCIA O AMENAZA, TOMA LOCALES, OBSTACULIZA VÍAS DE COMUNICACIÓN O IMPIDE EL LIBRE TRÁNSITO DE LA CIUDADANÍA O PERTURBA EL NORMAL FUNCIONAMIENTO DE LOS SERVICIOS PÚBLICOS O LA EJECUCIÓN DE OBRAS LEGALMENTE AUTORIZADAS, CON EL OBJETO DE OBTENER DE LAS AUTORIDADES CUALQUIER BENEFICIO O VENTAJA ECONÓMICA INDEBIDA U OTRA VENTAJA DE CUALQUIER OTRA ÍNDOLE COMETE DELITO:.', 'CONTRA EL PATRIMONIO-EXTORSIÓN.', 'ART. 200', '184211'),
    (2070, 'SUB-2070', 'SBM4', '¿CUÁL DE LOS SIGUIENTES ENUNCIADOS, ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE EXTORSIÓN?:', 'EN AGRAVIO DE REPRESENTANTE DIPLOMÁTICO.', 'ART. 200', '184212'),
    (2071, 'SUB-2071', 'SBM4', '¿CUÁL DE LOS SIGUIENTES ENUNCIADOS, NO ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE EXTORSIÓN?:', 'EN AGRAVIO DE INTEGRANTE DEL SINDICATO DE CONSTRUCCIÓN CIVIL.', 'ART. 200', '184213'),
    (2072, 'SUB-2072', 'SBM4', '¿CUÁL DE LOS SIGUIENTES ENUNCIADOS, NO ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE EXTORSIÓN?:', 'APROVECHANDO SU CONDICIÓN DE PROPIETARIO DE OBRA DE CONSTRUCCIÓN CIVIL.', 'ART. 200', '184214'),
    (2073, 'SUB-2073', 'SBM4', 'EL QUE, HACIENDO SABER A OTRO QUE SE DISPONE A PUBLICAR, DENUNCIAR O REVELAR UN HECHO O CONDUCTA CUYA DIVULGACIÓN PUEDE PERJUDICARLO PERSONALMENTE O A UN TERCERO CON QUIEN ESTÉ ESTRECHAMENTE VINCULADO, TRATA DE DETERMINARLO O LO DETERMINA A COMPRAR SU SILENCIO, COMETE DELITO DE:.', 'CONTRA EL PATRIMONIO – CHANTAJE.', 'ART. 201', '184215'),
    (2074, 'SUB-2074', 'SBM4', 'EL QUE, ILEGITIMAMENTE, INGRESA A UN INMUEBLE MEDIANTE ACTOS OCULTOS, EN AUSENCIA DEL POSEEDOR O CON PRECAUCIONES PARA ASEGURARSE EL DESCONOCIMIENTO DE QUIENES TENGAN DERECHO A OPONERSE, COMETE DELITO DE:', 'CONTRA EL PATRIMONIO – USURPACIÓN.', 'ART. 202', '184216'),
    (2075, 'SUB-2075', 'SBM4', '¿CUÁL DE LOS SIGUIENTES ENUNCIADOS, ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE USURPACIÓN?:', 'USANDO SUSTANCIAS PELIGROSAS.', 'ART. 204', '184217'),
    (2076, 'SUB-2076', 'SBM4', 'TODOS LOS DONATIVOS DADIVAS O PRESENTES RECIBIDOS POR FUNCIONARIOS Y/O SERVIDORES PÚBLICOS DE MANERA ILÍCITA SERÁN. Código Penal', 'DECOMISADOS.', 'ART. 401 - A', '184218'),
    (2077, 'SUB-2077', 'SBM4', '¿CUÁL DE LOS SIGUIENTES ENUNCIADOS, ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE USURPACIÓN?:', 'AFECTANDO LA LIBRE CIRCULACIÓN EN VÍAS DE COMUNICACIÓN.', 'ART. 204', '184219'),
    (2078, 'SUB-2078', 'SBM4', 'EL QUE DENUNCIA A LA AUTORIDAD UN HECHO PUNIBLE, A SABIENDAS DE QUE NO SE HA COMETIDO O QUE HA SIDO POR PERSONA DISTINTA A LA DENUNCIADA, COMETE DELITO DE:.', 'DENUNCIA CALUMNIOSA.', 'ART. 402', '184220'),
    (2079, 'SUB-2079', 'SBM4', 'EL QUE, ESTANDO LEGALMENTE PRIVADO DE SU LIBERTAD, SE EVADE POR MEDIO DE LA VIOLENCIA O AMENAZA, COMETE DELITO DE:.', 'EVASION MEDIANTE VIOLENCIA O AMENAZA.', 'ART. 413', '184221'),
    (2080, 'SUB-2080', 'SBM4', '¿CUAL DE LOS SIGUIENTES ENUNCIADOS, NO ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE USURPACIÓN?:', 'COLOCANDO ANIMALES.', 'ART. 204', '184222'),
    (2081, 'SUB-2081', 'SBM4', '¿CUAL DE LOS SIGUIENTES ENUNCIADOS, NO ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE USURPACIÓN?:.', 'DESVIANDO EL CURSO DE AGUAS PUBLICAS.', 'ART. 204', '184223'),
    (2082, 'SUB-2082', 'SBM4', 'EL QUE COMETE ACTOS DE CRUELDAD CONTRA UN ANIMAL DOMESTICO O UN ANIMAL SILVESTRE, O LOS ABANDONA, COMETE EL DELITO:.', 'ABANDONO Y ACTOS DE CRUELDAD CONTRA ANIMALES DOMESTICOS Y SILVESTRES.', 'ART. 206 - A', '184225'),
    (2083, 'SUB-2083', 'SBM4', 'EL QUE CAUSA DESORDEN EN LA SALA DE SESIONES DEL CONGRESO O DE LAS CÁMARAS LEGISLATIVAS, DE LAS ASAMBLEAS REGIONALES, DE LOS CONSEJOS MUNICIPALES O DE LOS TRIBUNALES DE JUSTICIA U OTRO LUGAR DONDE LAS AUTORIDADES PÚBLICAS EJERCEN SUS FUNCIONES O EL QUE ENTRA ARMADO EN DICHOS LUGARES, COMETE EL DELITO:.', 'PERTURBACIÓN DEL ORDEN EN EL LUGAR DONDE LA AUTORIDAD EJERCE SU FUNCIÓN', 'ART. 375', '184226'),
    (2084, 'SUB-2084', 'SBM4', 'CUAL DE LOS SIGUIENTES ENUNCIADOS, ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE PROXENETISMO.', 'EL PROXENETISMO SEA UN MEDIO DE SUBSISTENCIA DEL AGENTE.', 'ART. 181', '184227'),
    (2085, 'SUB-2085', 'SBM4', 'AL QUE CON LA FINALIDAD DE CONTRIBUIR A LA COMISIÓN DEL DELITO DE SECUESTRO, SUMINISTRA INFORMACIÓN QUE HAYA CONOCIDO POR RAZÓN O CON OCASIÓN DE SUS FUNCIONES, CARGO U OFICIO, O PROPORCIONA DELIBERADAMENTE LOS MEDIOS PARA LA PERPETRACIÓN DEL DELITO, SE LE APLICARÁ:', 'LA MISMA PENA.', 'ART. 152', '184228'),
    (2086, 'SUB-2086', 'SBM4', '¿CUÁL DE LOS SIGUIENTES ENUNCIADOS, NO ES UNA CIRCUNSTANCIA AGRAVANTE DEL DELITO DE SECUESTRO?:', 'SE COMETE PARA OBTENER TEJIDOS SOMÁTICOS DEL AGRAVIADO.', 'ART. 152', '184229'),
    (2087, 'SUB-2087', 'SBM4', 'EL QUE MATA A OTRO CON GRAN CRUELDAD O ALEVOSIA, QUE DELITO COMETE:.', 'HOMICIDIO CALIFICADO.', 'ART. 108', '184231'),
    (2088, 'SUB-2088', 'SBM4', 'EL QUE MATA A UNA MUJER POR SU CONDICION DE TAL DENTRO DEL CONTEXTO DE LA VIOLENCIA FAMILIAR, QUE DELITO COMETE:.', 'FEMINICIDIO.', 'ART. 108 - B', '184232'),
    (2089, 'SUB-2089', 'SBM4', 'EL QUE MATA A OTRO POR ORDEN, ENCARGO O ACUERDO CON EL PROPOSITO DE OBTENER PARA SI O PARA OTRO UN BENEFICIO ECONOMICO, QUE DELITO COMETE:.', 'SICARIATO.', 'ART. 108 - C', '184233'),
    (2090, 'SUB-2090', 'SBM4', 'EL QUE MATA A OTRO BAJO EL IMPERIO DE UNA EMOCION VIOLENTA QUE LAS CIRCUNSTANCIAS HACEN EXCUSABLE, QUE DELITO COMETE:.', 'HOMICIDIO POR EMOCION VIOLENTA.', 'ART. 109', '184234'),
    (2091, 'SUB-2091', 'SBM4', 'LA MADRE QUE MATA A SU HIJO DURANTE EL PARTO O BAJO LA INFLUENCIA DEL ESTADO PUERPERAL, QUE DELITO COMETE:.', 'INFANTICIDIO.', 'ART. 110', '184235'),
    (2092, 'SUB-2092', 'SBM4', 'EL QUE CAUSA EL ABORTO CON EL CONSENTIMIENTO DE LA GESTANTE, QUE DELITO COMETE:.', 'ABORTO CONSENTIDO.', 'ART. 115', '184237'),
    (2093, 'SUB-2093', 'SBM4', 'EL QUE HACE ABORTAR A UNA MUJER SIN SU CONSENTIMIENTO, QUE DELITO COMETE:.', 'ABORTO SIN CONSENTIMIENTO.', 'ART. 116', '184238'),
    (2094, 'SUB-2094', 'SBM4', 'EL QUE, CON VIOLENCIA OCASIONA UN ABORTO, SIN HABER TENIDO EL PROPOSITO DE CAUSARLO, COMETE DELITO DE:.', 'ABORTO PRETERINTENCIONAL.', 'ART. 118', '184239'),
    (2095, 'SUB-2095', 'SBM4', 'EL QUE CAUSA A OTRO DAÑO GRAVE EN EL CUERPO O EN LA SALUD FISICA O MENTAL, PONIENDO EN PELIGRO INMINENTE LA VIDA DE LA VICTIMA, COMETE DELITO DE:.', 'LESIONES GRAVES.', 'ART. 121', '184240'),
    (2096, 'SUB-2096', 'SBM4', 'EL QUE CAUSA A OTRO LESIONES EN EL CUERPO O EN LA SALUD FISICA O MENTAL QUE REQUIERA MAS DE DIEZ Y MENOS DE VEINTE DIAS DE ASISTENCIA O DESCANSO, SEGÚN PRESCRIPCION FACULTATIVA, QUE DELITO COMETE:.', 'LESIONES LEVES.', 'ART. 122', '184241'),
    (2097, 'SUB-2097', 'SBM4', 'EL QUE POR CULPA CAUSA A OTRO UN DAÑO EN EL CUERPO O EN LA SALUD QUE DELITO COMETE:.', 'LESIONES CULPOSAS.', 'ART. 124', '184242'),
    (2098, 'SUB-2098', 'SBM4', 'EL QUE MEDIANTE AMENAZA O VIOLENCIA OBLIGA A OTRO A HACER LO QUE LA LEY NO MANDA O LE IMPIDE HACER LO QUE ELLA NO PROHIBE, COMETE DELITO DE:.', 'COACCION.', 'ART. 151', '184243'),
    (2099, 'SUB-2099', 'SBM4', 'EL QUE SIN DERECHO, MOTIVO NI FACULTAD JUSTIFICADA, PRIVA A OTRO DE SU LIBERTAD PERSONAL, CUALQUIERA SEA EL MOVIL, EL PROPOSITO, LA MODALIDAD O CIRCUNSTANCIA O TIEMPO QUE EL AGRAVIADO SUFRA LA PRIVACION O RESTRICCION DE SU LIBERTAD, COMETE DELITO DE:.', 'SECUESTRO.', 'ART. 152', '184244'),
    (2100, 'SUB-2100', 'SBM4', 'EL QUE, EN LUGAR PUBLICO O PONIENDO EN RIESGO BIENES JURIDICOS DE TERCEROS Y TENIENDO LICENCIA PARA PORTAR ARMA DE FUEGO, HACE USO, MANIOBRA O DE CUALQUIER FORMA MANIPULA LA MISMA EN ESTADO DE EBRIEDAD, CON PRESENCIA DE ALCOHOL EN LA SANGRE EN PROPORCION MAYOR DE 0.5 GRAMOS-LITRO O BAJO EL EFECTO DE ESTUPEFACIENTES, DROGAS TOXICAS, SUSTANCIAS PSICOTROPICAS O SINTETICAS, COMETE DELITO DE:.', 'USO DE ARMAS EN ESTADO DE EBRIEDAD O DROGADICCION.', 'ART. 279 - F', '184245')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

